// Flashcard decks. Each card: what the term means in plain words, a concrete example where it helps,
// the trap that catches people, and optionally a small diagram (see CardFigure in Flashcards.jsx).
export const DECKS = [
  { id: 'consulting', name: 'Consulting language', blurb: 'The words interviewers use, and what they actually ask for.' },
  { id: 'accounting', name: 'Accounting', blurb: 'How the three statements fit together.' },
  { id: 'finance', name: 'Corporate finance', blurb: 'Cash, returns and what a business is worth.' },
  { id: 'trading', name: 'Trading and markets', blurb: 'Prices, risk and how positions actually make money.' },
  { id: 'statistics', name: 'Statistics', blurb: 'Reading data without fooling yourself.' },
  { id: 'maths', name: 'Case maths', blurb: 'The arithmetic worth knowing cold.' },
  { id: 'economics', name: 'Economics', blurb: 'Supply, demand and competition.' },
  { id: 'operations', name: 'Operations', blurb: 'Capacity, flow and inventory.' },
  { id: 'marketing', name: 'Customers', blurb: 'Segments, acquisition and retention.' },
  { id: 'vocab', name: 'GRE vocabulary', blurb: 'Hard words, in plain English, with the word each is confused with.' },
  { id: 'industry', name: 'Sector terms', blurb: 'Metrics that come up in aviation, retail, banking, telecom and more.' },
  { id: 'frameworks', name: 'Frameworks', blurb: 'The structures interviewers expect you to know, and when each one misleads.' },
  { id: 'strategy', name: 'Strategy concepts', blurb: 'The mechanisms behind the frameworks: moats, scale, switching costs and platforms.' },
]

export const CARDS = [
  // ---------- Consulting language ----------
  { id: 'mece', deck: 'consulting', term: 'MECE', short: 'Mutually exclusive, collectively exhaustive', definition: 'Branches that do not overlap and together cover the whole problem. It is a test you apply to a structure, not a reason to add more boxes.', example: 'Splitting profit into revenue and cost is MECE. Splitting customers into "young" and "students" is not, because one person can be both.', trap: 'Listing every branch you can think of instead of the few that decide the answer.' },
  { id: 'issue-tree', deck: 'consulting', term: 'Issue tree', definition: 'A problem broken into branches you can test one at a time, usually following the drivers of the number in question.', example: 'Profit splits into revenue and cost; revenue into price and volume; volume into customers and purchases each.', trap: 'Branching by topic, such as marketing or operations, instead of by what moves the number.', figure: 'tree' },
  { id: 'hypothesis', deck: 'consulting', term: 'Hypothesis-driven', definition: 'Start from a provisional answer, then look for the evidence that would prove it wrong. It keeps the analysis short.', example: '"Margin fell because discounting rose." Now go and check discounts before anything else.', trap: 'Collecting data first and hoping a conclusion appears.' },
  { id: 'pareto', deck: 'consulting', term: 'The 80/20 rule', definition: 'A small share of causes usually drives most of the effect, so size each branch before analysing it.', example: 'If three of forty products make 70% of profit, start there.', trap: 'Spending equal time on a branch worth 2% of the problem.' },
  { id: 'value-chain', deck: 'consulting', term: 'Value chain', definition: 'The sequence of activities from raw inputs to the customer. Use it to locate where cost sits and where value is added.', example: 'For a retailer: buying, warehousing, transport, store operations, service.', trap: 'Listing the chain without asking which steps the client actually controls.' },
  { id: 'five-forces', deck: 'consulting', term: 'Five forces', definition: 'Rivalry, substitutes, new entrants, supplier power and buyer power: a check on whether an industry can be profitable at all.', trap: 'Describing each force instead of saying what it means for this decision.' },
  { id: 'bcg-matrix', deck: 'consulting', term: 'Growth-share matrix', definition: 'Sorts a portfolio by market growth and relative market share to show what to fund, hold, or exit.', example: 'High growth and high share is worth funding; low growth and low share usually is not.', trap: 'Using it on a single-product business, where it says nothing.' },
  { id: 'three-cs', deck: 'consulting', term: '3Cs', definition: 'Customer, competition, company: a quick frame for whether a move fits the market and the client’s own strengths.', trap: 'Treating it as an answer rather than a list of questions.' },
  { id: 'four-ps', deck: 'consulting', term: '4Ps', definition: 'Product, price, place, promotion: the levers for taking something to market.', trap: 'Reciting all four when only price and place matter to the question.' },
  { id: 'swot', deck: 'consulting', term: 'SWOT', definition: 'Strengths, weaknesses, opportunities, threats. Strengths and weaknesses are internal; opportunities and threats are external.', trap: 'Producing a list with no recommendation attached to it.' },
  { id: 'benchmark', deck: 'consulting', term: 'Benchmarking', definition: 'Comparing the client with peers, or with its own past, to tell a company problem from an industry one.', example: 'If every airline lost margin last year, fuel is a likelier cause than the client’s own pricing.', trap: 'Comparing totals when scale, units or time periods differ.' },
  { id: 'sanity-check', deck: 'consulting', term: 'Sanity check', definition: 'Testing an answer against something you already know, such as a familiar price or a per-person figure.', example: 'A market size of $50,000 per household a year on food is worth double checking.', trap: 'Presenting a number nobody has tested for plausibility.' },
  { id: 'synergy', deck: 'consulting', term: 'Synergies', definition: 'Value that exists only if two businesses combine: extra revenue or lower cost, less what it costs to achieve.', example: 'Closing one of two overlapping warehouses after a merger.', trap: 'Counting savings either company could have achieved alone.' },
  { id: 'cannibalisation', deck: 'consulting', term: 'Cannibalisation', definition: 'New sales taken from your own existing product rather than from the market or a rival.', example: 'A cheaper own-brand that mostly converts buyers of your premium line.', trap: 'Reporting gross new sales as if all of it were incremental.' },
  { id: 'willingness', deck: 'consulting', term: 'Willingness to pay', definition: 'The most a customer would pay, set by the value of the next best alternative they give up.', example: 'A part that avoids a day of downtime is worth close to a day of lost output.', trap: 'Setting price from your own cost instead of the customer’s alternative.' },
  { id: 'incremental', deck: 'consulting', term: 'Incremental', definition: 'The change caused by a decision. Count only the revenue and cost that would not exist otherwise.', example: 'An extra flight adds fuel and crew, not the head office rent.', trap: 'Including sunk costs or spending that happens either way.' },
  { id: 'no-regret', deck: 'consulting', term: 'No-regret move', definition: 'An action worth taking in every scenario you considered, so it can start before the uncertainty resolves.', trap: 'Calling a large, hard-to-reverse bet a no-regret move.' },
  { id: 'so-what', deck: 'consulting', term: 'So what?', definition: 'The implication of a finding: what the client should do differently because of it.', example: '"Churn is 9% a month" becomes "we lose the customer before acquisition pays back, so fix onboarding first."', trap: 'Presenting an observation and stopping there.' },
  { id: 'top-down', deck: 'consulting', term: 'Top-down vs bottom-up', definition: 'Top-down starts from a big number and narrows it; bottom-up builds from units. Doing both and comparing is the real check.', example: 'Top-down: population times spend. Bottom-up: stores times customers times basket.', trap: 'Trusting one route when the two answers differ by more than a little.' },
  { id: 'driver-tree', deck: 'consulting', term: 'Driver tree', definition: 'A number decomposed into the levers that produce it, so you can see which lever the client can actually move.', example: 'Revenue = traffic × conversion × basket size.', trap: 'Stopping at a level where nothing is controllable.' },
  { id: 'core-competence', deck: 'consulting', term: 'Core competence', definition: 'Something the company does better than others and that customers value, which is hard to copy.', trap: 'Calling anything the company happens to do a competence.' },
  { id: 'scale', deck: 'consulting', term: 'Economies of scale', definition: 'Unit cost falls as volume rises, because fixed costs spread over more units and buying power improves.', example: 'A plant with $100 million of fixed cost costs $1,000 a unit at 100,000 units and $500 at 200,000.', trap: 'Assuming scale helps when most costs are variable.', figure: 'scale' },
  { id: 'scope', deck: 'consulting', term: 'Economies of scope', definition: 'Cost falls because several products share the same assets, teams or channels.', example: 'One delivery van carrying groceries and parcels on the same route.', trap: 'Confusing it with scale, which is about more of the same product.' },
  { id: 'experience-curve', deck: 'consulting', term: 'Experience curve', definition: 'Unit cost falls a predictable amount each time cumulative output doubles, as people and processes improve.', trap: 'Expecting it without investment in how the work is actually done.' },
  { id: 'first-mover', deck: 'consulting', term: 'First-mover advantage', definition: 'Being early pays when it locks in customers, supply or standards, and not otherwise.', trap: 'Assuming early always wins; fast followers often learn from the pioneer’s mistakes.' },
  { id: 'switching-costs', deck: 'consulting', term: 'Switching costs', definition: 'What a customer gives up to move to a rival: money, effort, data, retraining or risk.', example: 'Moving a company’s payroll to another provider mid-year.', trap: 'Ignoring that high switching costs also make new customers harder to win.' },
  { id: 'network-effects', deck: 'consulting', term: 'Network effects', definition: 'The product becomes more valuable as more people use it, so share tends to concentrate.', example: 'A marketplace: more sellers attract more buyers, which attracts more sellers.', trap: 'Claiming them for a business where users do not benefit from each other.' },
  { id: 'barriers', deck: 'consulting', term: 'Barriers to entry', definition: 'What stops a new rival: capital, regulation, scale, brand, distribution, or technology.', trap: 'Treating a patent or a brand as permanent protection.' },
  { id: 'vertical-integration', deck: 'consulting', term: 'Vertical integration', definition: 'Owning a step up or down your own chain, such as your supplier or your distributor.', example: 'A coffee chain buying its own roasting plant.', trap: 'Buying a step that adds cost and fixed assets without improving service or price.' },
  { id: 'make-or-buy', deck: 'consulting', term: 'Make or buy', definition: 'Whether to do something in house or pay someone else, judged on cost, control, quality and flexibility.', trap: 'Comparing in-house variable cost with a supplier’s full price.' },
  { id: 'pilot', deck: 'consulting', term: 'Pilot', definition: 'A small, time-boxed test with a success measure agreed in advance, used before a full rollout.', trap: 'Running a pilot with no criteria, so it never conclusively ends.' },
  { id: 'stakeholder-map', deck: 'consulting', term: 'Stakeholder map', definition: 'Who is affected by a change, what they care about, and how much influence they hold.', trap: 'Designing a plan that the people who must deliver it will resist.' },
  { id: 'quick-win', deck: 'consulting', term: 'Quick win', definition: 'A change that pays back within weeks with little risk, useful for funding and credibility for bigger moves.', trap: 'Chasing only quick wins and never fixing the structural problem.' },
  { id: 'run-rate', deck: 'consulting', term: 'Run rate', definition: 'A recent period scaled to a year, to show where performance is heading now.', example: 'Last quarter’s $300 million revenue is a $1.2 billion run rate.', trap: 'Annualising a seasonal quarter as if it were typical.' },
  { id: 'like-for-like', deck: 'consulting', term: 'Like for like', definition: 'Comparing the same basis on both sides: same stores, same period, same currency, same definition.', trap: 'Reading growth that came from opening new stores as growth in existing ones.' },

  // ---------- Accounting ----------
  { id: 'pl', deck: 'accounting', term: 'Profit and loss statement', short: 'Income statement', definition: 'Revenue for a period, less the costs of earning it, ending at profit. It measures performance, not cash.', trap: 'Reading profit as cash: sales on credit appear here before the money arrives.' },
  { id: 'balance-sheet', deck: 'accounting', term: 'Balance sheet', definition: 'What the company owns and owes at one moment. Assets equal liabilities plus equity, always.', example: 'A $100 million machine bought with a $70 million loan adds $100 million of assets and $70 million of debt.', trap: 'Treating it as a period, when it is a single date.' },
  { id: 'cash-flow-statement', deck: 'accounting', term: 'Cash flow statement', definition: 'Cash in and out, split into operating, investing and financing. It reconciles profit to the change in the bank balance.', trap: 'Ignoring it because profit looks healthy; growing firms often run out of cash.' },
  { id: 'revenue-recognition', deck: 'accounting', term: 'Revenue recognition', definition: 'Revenue is recorded when the service or good is delivered, not when the cash arrives.', example: 'An annual subscription paid upfront is recognised across twelve months.', trap: 'Counting a signed contract as revenue on day one.' },
  { id: 'cogs', deck: 'accounting', term: 'Cost of goods sold', short: 'COGS', definition: 'The direct cost of what was actually sold: materials, production labour, freight in.', trap: 'Including overheads such as head office salaries, which belong below gross profit.' },
  { id: 'gross-profit', deck: 'accounting', term: 'Gross profit', definition: 'Revenue less cost of goods sold. It shows what each sale contributes before running the company.', example: '$100 revenue less $60 direct cost is $40 gross profit, a 40% gross margin.', trap: 'Comparing gross margin across firms that classify costs differently.', figure: 'waterfall' },
  { id: 'ebit', deck: 'accounting', term: 'Operating profit', short: 'EBIT', definition: 'Profit from the business itself, after all operating costs but before interest and tax.', trap: 'Comparing it across firms with very different lease or ownership choices.' },
  { id: 'ebitda-acc', deck: 'accounting', term: 'EBITDA', short: 'Earnings before interest, tax, depreciation and amortisation', definition: 'Operating profit with depreciation and amortisation added back, used as a rough proxy for operating cash.', example: 'EBIT of $500 million plus $200 million depreciation gives $700 million EBITDA.', trap: 'Calling it cash flow: it ignores capital spending, working capital, interest and tax.' },
  { id: 'net-income', deck: 'accounting', term: 'Net profit', definition: 'What is left after every cost, including interest and tax. It is what belongs to shareholders.', trap: 'Judging operations by net profit when one-off items distort it.' },
  { id: 'depreciation', deck: 'accounting', term: 'Depreciation', definition: 'Spreading the cost of a physical asset over the years it is used, so the cost sits in the years that benefit.', example: 'A $5 million machine used for ten years costs $500,000 a year.', trap: 'Treating it as cash leaving the business; the cash left when the asset was bought.' },
  { id: 'amortisation', deck: 'accounting', term: 'Amortisation', definition: 'The same idea as depreciation, applied to non-physical assets such as software or licences.', trap: 'Mixing it up with loan amortisation, which is repaying principal over time.' },
  { id: 'accruals', deck: 'accounting', term: 'Accrual accounting', definition: 'Record revenue and cost when they happen, not when cash moves. It is why profit and cash differ.', example: 'Electricity used in March is a March cost even if the bill is paid in April.', trap: 'Reading a profitable month as a month with more money in the bank.' },
  { id: 'receivables', deck: 'accounting', term: 'Receivables', definition: 'Money customers owe for goods already delivered. It is revenue earned but not yet collected.', example: 'Sixty days of receivables on $360 million of annual sales ties up about $60 million.', trap: 'Growing sales on credit to customers who pay slowly, or not at all.' },
  { id: 'payables', deck: 'accounting', term: 'Payables', definition: 'Money the company owes suppliers for goods already received. Paying later is free financing, within reason.', trap: 'Stretching suppliers so far that prices rise or supply stops.' },
  { id: 'inventory', deck: 'accounting', term: 'Inventory', definition: 'Goods held for sale, plus materials and part-finished work. It is cash sitting on shelves.', trap: 'Judging it by value alone rather than by how fast it sells.' },
  { id: 'working-capital-acc', deck: 'accounting', term: 'Working capital', definition: 'Receivables plus inventory, less payables: the cash tied up in day-to-day operations.', example: 'Collect in 60 days, hold stock 30 days, pay suppliers in 45: 45 days of sales are tied up.', trap: 'Forgetting that fast growth consumes cash even while profit rises.', figure: 'cash-cycle' },
  { id: 'current-ratio', deck: 'accounting', term: 'Current ratio', definition: 'Current assets divided by current liabilities: can short-term obligations be met from short-term assets?', trap: 'Reading a high ratio as strength when it is slow-moving inventory.' },
  { id: 'equity', deck: 'accounting', term: 'Equity', definition: 'What owners would be left with after selling assets and paying every debt: assets less liabilities.', trap: 'Confusing it with cash or with the company’s market value.' },
  { id: 'retained-earnings', deck: 'accounting', term: 'Retained earnings', definition: 'Profits kept in the business over its life rather than paid out as dividends.', trap: 'Assuming retained earnings sit in the bank; they are usually invested in assets.' },
  { id: 'goodwill', deck: 'accounting', term: 'Goodwill', definition: 'The premium paid to buy a company above the value of its identifiable assets, recorded as an asset.', trap: 'Forgetting it can be written down later, which admits the price was too high.' },
  { id: 'provision', deck: 'accounting', term: 'Provision', definition: 'An amount set aside for a cost that is likely but not yet paid, such as warranty claims or bad debts.', trap: 'Using provisions to smooth profit between years.' },
  { id: 'deferred-revenue', deck: 'accounting', term: 'Deferred revenue', definition: 'Cash received before delivery. It is a liability until the service is provided.', example: 'A gym collects a year of fees in January and owes eleven months of service.', trap: 'Spending it as if it were earned revenue.' },
  { id: 'capex-opex-acc', deck: 'accounting', term: 'Capex vs opex', definition: 'Capital spending buys assets used for years and appears on the balance sheet. Operating spending is consumed now and hits profit now.', trap: 'Comparing two options when one is bought and the other rented.' },
  { id: 'fixed-variable', deck: 'accounting', term: 'Fixed vs variable cost', definition: 'Fixed costs stay the same as volume changes; variable costs move with each unit produced.', example: 'Rent is fixed; packaging is variable.', trap: 'Treating a cost as fixed forever: staff and space change over a longer horizon.' },
  { id: 'direct-indirect', deck: 'accounting', term: 'Direct vs indirect cost', definition: 'Direct costs can be traced to one product or customer; indirect costs are shared and must be allocated.', trap: 'Letting an arbitrary allocation decide which product looks profitable.' },
  { id: 'contribution-acc', deck: 'accounting', term: 'Contribution margin', definition: 'Price less variable cost per unit: what each extra sale contributes towards fixed costs and profit.', example: 'A $250 ticket with $90 of variable cost contributes $160.', trap: 'Subtracting a share of fixed cost, which turns it into a profit margin instead.' },
  { id: 'break-even-acc', deck: 'accounting', term: 'Break-even point', definition: 'The volume at which contribution exactly covers fixed costs, so profit is zero.', example: '$800,000 of fixed cost ÷ $160 contribution = 5,000 tickets.', trap: 'Dividing fixed costs by price instead of by contribution.', figure: 'breakeven' },
  { id: 'operating-leverage-acc', deck: 'accounting', term: 'Operating leverage', definition: 'How sharply profit moves when volume moves, driven by the share of costs that are fixed.', example: 'With mostly fixed costs, 10% more volume can lift profit by 40%.', trap: 'Forgetting it works just as violently on the way down.' },
  { id: 'sunk-cost', deck: 'accounting', term: 'Sunk cost', definition: 'Money already spent that no decision can recover, so it should not affect the choice ahead.', example: 'Research already paid for does not justify launching a product that loses money.', trap: 'Continuing a project to avoid admitting the earlier spend was wasted.' },
  { id: 'opportunity-cost', deck: 'accounting', term: 'Opportunity cost', definition: 'The value of the best option you give up by choosing this one. It is a real cost even when no cash moves.', example: 'Using a warehouse yourself costs the rent you could have earned on it.', trap: 'Treating an owned asset as free because no cash changes hands.' },
  // ---------- Corporate finance ----------
  { id: 'time-value', deck: 'finance', term: 'Time value of money', definition: 'A dollar today is worth more than a dollar later, because today’s dollar can be invested or spent now and carries no risk of never arriving.', example: 'At 10%, $100 today is worth $110 in a year, so $110 next year is worth $100 now.', trap: 'Adding cash flows from different years without discounting them first.', figure: 'timeline' },
  { id: 'discount-rate', deck: 'finance', term: 'Discount rate', definition: 'The annual rate used to convert future cash into today’s value. It reflects what the money could earn elsewhere at similar risk.', trap: 'Using one rate for projects with very different risk.' },
  { id: 'present-value', deck: 'finance', term: 'Present value', definition: 'A future amount expressed in today’s money: future cash divided by (1 + rate) raised to the number of years.', example: '$121 in two years at 10% is $121 ÷ 1.21 = $100 today.', trap: 'Discounting profit instead of cash.' },
  { id: 'npv-fin', deck: 'finance', term: 'Net present value', short: 'NPV', definition: 'The present value of all future cash flows less the investment. Positive means the project earns more than the required return.', trap: 'Ignoring the value of what happens after the forecast ends.' },
  { id: 'irr-fin', deck: 'finance', term: 'Internal rate of return', short: 'IRR', definition: 'The discount rate at which net present value is zero, so it is the project’s own annual return. Compare it with the cost of capital.', trap: 'Choosing a high return on a tiny project over more total value.' },
  { id: 'payback-fin', deck: 'finance', term: 'Payback period', definition: 'How long the extra cash generated takes to repay the extra investment. Shorter payback means less exposure to being wrong.', example: '$8 million invested returning $1.5 million a year pays back in 5.3 years.', trap: 'Ignoring everything after payback, and ignoring the time value of money.' },
  { id: 'hurdle-rate', deck: 'finance', term: 'Hurdle rate', definition: 'The minimum return a company demands before approving an investment, usually its cost of capital plus a margin.', trap: 'Quietly lowering the hurdle to make a favoured project work.' },
  { id: 'wacc-fin', deck: 'finance', term: 'Cost of capital', short: 'WACC', definition: 'The blended return that lenders and shareholders require, weighted by how much of each the company uses.', trap: 'Using the company rate for a project in a riskier business.' },
  { id: 'cost-of-equity', deck: 'finance', term: 'Cost of equity', definition: 'The return shareholders expect for holding the shares, given the risk. It is higher than the cost of debt because they are paid last.', trap: 'Treating equity as free because dividends are optional.' },
  { id: 'capm', deck: 'finance', term: 'CAPM', short: 'Capital asset pricing model', definition: 'Estimates the cost of equity as the risk-free rate plus beta times the extra return investors expect from the market.', trap: 'Trusting the output precisely when every input is an estimate.' },
  { id: 'beta-fin', deck: 'finance', term: 'Beta', definition: 'How much a share moves relative to the market. Beta of 1.5 means it tends to move 50% more than the index, both ways.', trap: 'Reading beta as total risk; it only measures the part that moves with the market.' },
  { id: 'dcf', deck: 'finance', term: 'Discounted cash flow', short: 'DCF', definition: 'Valuing a business by forecasting its future cash and discounting it to today.', trap: 'Letting the terminal value carry almost all of the answer without testing it.' },
  { id: 'terminal-value', deck: 'finance', term: 'Terminal value', definition: 'The value of all cash beyond the forecast period, usually assuming steady growth for ever.', trap: 'Assuming a growth rate above the economy’s, which no business sustains for ever.' },
  { id: 'enterprise-value', deck: 'finance', term: 'Enterprise value', definition: 'The value of the whole business regardless of how it is financed: equity value plus debt, less cash.', example: 'Equity of $8 billion with $3 billion debt and $1 billion cash gives an enterprise value of $10 billion.', trap: 'Comparing enterprise value with a profit measure that is after interest.' },
  { id: 'ev-ebitda', deck: 'finance', term: 'EV/EBITDA', definition: 'Enterprise value divided by EBITDA: how many years of operating earnings the whole business costs.', trap: 'Comparing multiples across industries with different capital needs.' },
  { id: 'pe-ratio', deck: 'finance', term: 'Price to earnings', short: 'P/E', definition: 'Share price divided by earnings per share: what investors pay for each dollar of profit.', trap: 'Reading a high P/E as expensive without asking what growth is expected.' },
  { id: 'eps', deck: 'finance', term: 'Earnings per share', definition: 'Net profit divided by the number of shares. It shows profit per unit of ownership.', trap: 'Celebrating growth that came only from buying back shares.' },
  { id: 'free-cash-flow-fin', deck: 'finance', term: 'Free cash flow', definition: 'Cash from operations after the capital spending needed to keep the business running. It is what can fund debt, dividends or growth.', trap: 'Ignoring the spending needed just to stand still.' },
  { id: 'leverage-fin', deck: 'finance', term: 'Leverage', definition: 'Using borrowed money to fund assets. It lifts returns when things go well and deepens losses when they do not.', example: 'A 10% gain on assets funded half by debt roughly doubles the return on equity, before interest.', trap: 'Judging leverage without asking how stable the cash flows are.' },
  { id: 'debt-ebitda', deck: 'finance', term: 'Debt to EBITDA', definition: 'How many years of operating earnings it would take to repay debt. Lenders use it as a quick risk gauge.', trap: 'Comparing across sectors: stable utilities carry far more than cyclical firms.' },
  { id: 'interest-cover', deck: 'finance', term: 'Interest cover', definition: 'Operating profit divided by interest cost: how many times over the company can pay its interest bill.', trap: 'Looking at one good year rather than the worst plausible one.' },
  { id: 'roe', deck: 'finance', term: 'Return on equity', definition: 'Net profit divided by shareholders’ equity: the return generated on owners’ money.', trap: 'Admiring a high figure that comes from heavy borrowing rather than good operations.' },
  { id: 'roic', deck: 'finance', term: 'Return on invested capital', definition: 'Operating profit after tax divided by the capital used to earn it. Above the cost of capital, growth creates value; below, it destroys value.', trap: 'Growing a business whose returns sit below its cost of capital.' },
  { id: 'dupont', deck: 'finance', term: 'DuPont breakdown', definition: 'Splits return on equity into margin, asset turnover and leverage, so you can see which one is driving it.', trap: 'Reporting the ratio without saying which of the three moved.' },
  { id: 'unit-economics-fin', deck: 'finance', term: 'Unit economics', definition: 'Revenue and cost for a single unit, customer or order, to show whether scale will help or hurt.', trap: 'Spreading fixed cost over a volume the business has not reached.' },
  { id: 'ltv-cac-fin', deck: 'finance', term: 'LTV to CAC', definition: 'Lifetime value of a customer against the cost of acquiring one. It tests whether growth spending pays back.', example: 'A customer worth $9,000 acquired for $3,000 gives a ratio of 3.', trap: 'Building lifetime value on a retention rate you have not measured.' },
  { id: 'burn-runway', deck: 'finance', term: 'Burn rate and runway', definition: 'Burn is net cash spent each month; runway is cash divided by burn, so how many months remain.', example: '$120 million in the bank and $10 million a month burn is a twelve-month runway.', trap: 'Using last month’s burn when hiring is about to increase it.' },
  { id: 'sensitivity', deck: 'finance', term: 'Sensitivity analysis', definition: 'Changing one assumption at a time to see which ones actually move the answer.', trap: 'Flexing everything at once, which hides the driver that matters.' },
  { id: 'scenario', deck: 'finance', term: 'Scenario analysis', definition: 'Building a small number of coherent futures, such as base, upside and downside, with consistent assumptions in each.', trap: 'Mixing a pessimistic price with an optimistic volume in the same case.' },
  { id: 'break-even-analysis', deck: 'finance', term: 'Break-even analysis', definition: 'Working out the volume, price or cost at which a decision stops losing money, which frames how much has to go right.', trap: 'Presenting one break-even number without saying how likely it is.' },

  // ---------- Trading and markets ----------
  { id: 'bid-ask', deck: 'trading', term: 'Bid and ask', definition: 'The bid is the highest price a buyer will pay; the ask is the lowest price a seller will accept. The gap between them is the spread.', example: 'Bid $100.1, ask $100.2: buying then selling immediately loses $0.1 a share.', trap: 'Quoting a mid price as if you could trade there.', figure: 'spread' },
  { id: 'spread', deck: 'trading', term: 'Spread', definition: 'The cost of trading immediately, set by the gap between bid and ask. It widens when markets are uncertain or thin.', trap: 'Ignoring it in a strategy that trades often; small spreads compound quickly.', figure: 'spread' },
  { id: 'liquidity', deck: 'trading', term: 'Liquidity', definition: 'How easily you can trade size without moving the price. Deep markets absorb large orders; thin ones do not.', trap: 'Sizing a position you can enter but not exit.' },
  { id: 'order-book', deck: 'trading', term: 'Order book', definition: 'The live list of buy and sell orders at each price. It shows where demand and supply currently sit.', trap: 'Trusting visible size; large orders are often hidden or cancelled.' },
  { id: 'market-order', deck: 'trading', term: 'Market vs limit order', definition: 'A market order trades now at whatever price is available. A limit order sets your price and may never fill.', trap: 'Sending a market order into a thin book and paying far more than expected.' },
  { id: 'slippage', deck: 'trading', term: 'Slippage', definition: 'The difference between the price you expected and the price you got, usually from moving the market or delay.', trap: 'Backtesting a strategy at mid prices and ignoring what filling costs.' },
  { id: 'long-short', deck: 'trading', term: 'Long and short', definition: 'Long profits when the price rises. Short sells borrowed stock hoping to buy it back cheaper, so it profits when the price falls.', trap: 'Forgetting a short’s loss has no natural ceiling, because a price can keep rising.' },
  { id: 'leverage-trading', deck: 'trading', term: 'Leverage and margin', definition: 'Trading with borrowed money. Margin is the cash you post as security; leverage multiplies both gains and losses.', example: 'At five times leverage, a 20% move against you wipes out the margin.', trap: 'Sizing by what you can borrow rather than by what you can lose.' },
  { id: 'margin-call', deck: 'trading', term: 'Margin call', definition: 'A demand to post more cash when losses erode your margin. If you do not, the position is closed for you.', trap: 'Being forced out at the worst price precisely when you were right about the direction.' },
  { id: 'volatility', deck: 'trading', term: 'Volatility', definition: 'How much a price moves around, usually the standard deviation of returns. High volatility means wider swings, not a direction.', trap: 'Reading high volatility as a signal that prices will fall.' },
  { id: 'hedge', deck: 'trading', term: 'Hedge', definition: 'A position taken to offset a risk you already carry, accepting less upside in exchange for less downside.', example: 'An airline buying fuel futures so a price rise does not wreck its costs.', trap: 'Calling a second speculative bet a hedge.' },
  { id: 'derivative', deck: 'trading', term: 'Derivative', definition: 'A contract whose value comes from something else: a share, an index, a commodity or a rate.', trap: 'Judging exposure by what the contract costs rather than the value it controls.' },
  { id: 'futures', deck: 'trading', term: 'Futures contract', definition: 'An agreement to buy or sell something at a set price on a future date. Both sides are obliged to settle.', trap: 'Forgetting that gains and losses are settled daily, which needs cash on hand.' },
  { id: 'call-option', deck: 'trading', term: 'Call option', definition: 'The right, not the obligation, to buy at a set price before expiry. The most a buyer can lose is the premium paid.', example: 'A $100 call bought for $5 makes money above $105 at expiry.', trap: 'Ignoring that the option expires worthless if the move happens too late.', figure: 'payoff' },
  { id: 'put-option', deck: 'trading', term: 'Put option', definition: 'The right to sell at a set price before expiry. It gains value when the price falls, so it works like insurance.', trap: 'Buying protection so far out of the money that it never pays.' },
  { id: 'strike-premium', deck: 'trading', term: 'Strike and premium', definition: 'The strike is the agreed price in an option; the premium is what the buyer pays for the right.', trap: 'Comparing premiums without noting different strikes and expiry dates.' },
  { id: 'arbitrage', deck: 'trading', term: 'Arbitrage', definition: 'Buying and selling the same risk in two places at different prices for a profit with little or no exposure.', trap: 'Calling a trade arbitrage when the two legs are similar but not identical.' },
  { id: 'stop-loss', deck: 'trading', term: 'Stop loss', definition: 'A pre-set exit that caps the loss on a position, decided before emotion arrives.', trap: 'Placing it where a normal daily swing will trigger it.' },
  { id: 'position-sizing', deck: 'trading', term: 'Position sizing', definition: 'Deciding how much to risk on one idea, usually a small fixed share of capital, so no single loss ends the game.', trap: 'Sizing by conviction rather than by what a loss would cost.' },
  { id: 'drawdown', deck: 'trading', term: 'Drawdown', definition: 'The fall from a peak to the low point that follows, the usual measure of how painful a strategy is to hold.', example: 'A 50% drawdown needs a 100% gain just to get back to level.', trap: 'Judging a strategy by total return while ignoring the depth of its drawdowns.', figure: 'drawdown' },
  { id: 'sharpe', deck: 'trading', term: 'Sharpe ratio', definition: 'Return above the risk-free rate divided by volatility: how much reward each unit of risk earned.', trap: 'Comparing ratios measured over different periods or frequencies.' },
  { id: 'alpha-beta', deck: 'trading', term: 'Alpha and beta', definition: 'Beta is the return that came from simply being in the market; alpha is what is left, the part attributable to skill.', trap: 'Charging for alpha that is really leverage on market exposure.' },
  { id: 'momentum', deck: 'trading', term: 'Momentum vs mean reversion', definition: 'Momentum assumes recent winners keep winning; mean reversion assumes prices return to an average. Each works in different regimes.', trap: 'Switching between the two after every loss.' },
  { id: 'bond-price', deck: 'trading', term: 'Bond price and yield', definition: 'Bond prices and yields move in opposite directions. If rates rise, existing bonds paying less become worth less.', example: 'A bond paying 5% falls in price when new bonds pay 7%.', trap: 'Assuming a bond is safe from loss if you might have to sell early.' },
  { id: 'duration', deck: 'trading', term: 'Duration', definition: 'How sensitive a bond’s price is to a change in rates. Duration of 7 means roughly 7% price fall for a 1 point rate rise.', trap: 'Confusing it with the years left to maturity.' },
  { id: 'yield-curve', deck: 'trading', term: 'Yield curve', definition: 'Yields plotted against maturity. It normally slopes up; an inverted curve means short rates exceed long ones.', trap: 'Reading every inversion as a precise recession timer.', figure: 'yield-curve' },
  { id: 'credit-spread', deck: 'trading', term: 'Credit spread', definition: 'The extra yield a borrower pays over a government bond of the same maturity: the market’s price for default risk.', trap: 'Reading a widening spread as only sentiment when funding may be drying up.' },
  { id: 'carry', deck: 'trading', term: 'Carry', definition: 'What a position earns or costs simply for being held: interest, dividends or storage, net of funding.', trap: 'Chasing carry into a position whose price risk dwarfs the yield.' },
  { id: 'mark-to-market', deck: 'trading', term: 'Mark to market', definition: 'Revaluing a position at today’s price, so unrealised gains and losses appear immediately.', trap: 'Treating a loss as unreal until sold, when margin calls treat it as very real.' },
  { id: 'market-maker', deck: 'trading', term: 'Market maker', definition: 'A firm quoting both a bid and an ask, earning the spread for providing liquidity and managing the inventory risk.', trap: 'Assuming quotes stay firm in fast markets.' },
  { id: 'short-squeeze', deck: 'trading', term: 'Short squeeze', definition: 'Rising prices force short sellers to buy back, which pushes prices higher and forces more buying.', trap: 'Holding a crowded short without room for the squeeze.' },
  { id: 'settlement', deck: 'trading', term: 'Settlement', definition: 'When cash and securities actually change hands, a day or more after the trade is agreed.', trap: 'Planning to spend the proceeds before they have settled.' },
  // ---------- Statistics ----------
  { id: 'mean-median', deck: 'statistics', term: 'Mean vs median', definition: 'The mean adds everything and divides; the median is the middle value. When a few large values pull the mean up, the median describes the typical case better.', example: 'Nine people earn $30,000 and one earns $3 million. The mean is about $300,000; the median is $30,000.', trap: 'Quoting an average income or basket size that no actual customer resembles.', figure: 'skew' },
  { id: 'mode', deck: 'statistics', term: 'Mode', definition: 'The most common value. It is the useful one for categories, such as the best selling size or colour.', trap: 'Reporting a mode from a tiny sample where ties are meaningless.' },
  { id: 'weighted-average-stats', deck: 'statistics', term: 'Weighted average', definition: 'An average where each value counts in proportion to its size, volume or frequency.', example: 'Two segments at 10% and 50% margin are not a 30% blend if the first sells ten times as much.', trap: 'Averaging percentages from groups of very different sizes.' },
  { id: 'range-iqr', deck: 'statistics', term: 'Range and interquartile range', definition: 'Range is highest less lowest. The interquartile range covers the middle half, so one freak value cannot distort it.', trap: 'Quoting the range when one outlier defines both ends.' },
  { id: 'variance', deck: 'statistics', term: 'Variance', definition: 'The average of squared distances from the mean. Squaring keeps everything positive and punishes big misses.', trap: 'Reporting it directly: the units are squared and hard to interpret.' },
  { id: 'standard-deviation', deck: 'statistics', term: 'Standard deviation', definition: 'The square root of variance, so it is a typical distance from the mean in the same units as the data.', example: 'Mean delivery 3 days with a standard deviation of 1 day means most deliveries land between 2 and 4.', trap: 'Comparing spread across data sets with very different averages.', figure: 'normal' },
  { id: 'coefficient-variation', deck: 'statistics', term: 'Coefficient of variation', definition: 'Standard deviation divided by the mean, so you can compare variability between things of different size.', trap: 'Using it when the mean is close to zero, where it explodes.' },
  { id: 'normal-distribution', deck: 'statistics', term: 'Normal distribution', definition: 'The symmetric bell shape where about 68% of values sit within one standard deviation of the mean and about 95% within two.', trap: 'Assuming it for data that cannot go below zero or has a long tail, such as income.', figure: 'normal' },
  { id: 'skew', deck: 'statistics', term: 'Skew', definition: 'A distribution with a long tail on one side. With a right tail, the mean sits above the median.', example: 'Customer spend: most people spend a little, a few spend a lot.', trap: 'Summarising skewed data with the mean alone.', figure: 'skew' },
  { id: 'percentile-stats', deck: 'statistics', term: 'Percentile', definition: 'The value below which a given share of observations falls. The 90th percentile is beaten by only 10%.', example: 'A 90th percentile delivery time of 5 days means 1 in 10 orders takes longer.', trap: 'Promising service levels on the average when customers feel the tail.' },
  { id: 'outlier-stats', deck: 'statistics', term: 'Outlier', definition: 'A value far from the rest. It can be an error, or the most informative point in the data set.', trap: 'Deleting outliers before asking why they exist.' },
  { id: 'correlation-stats', deck: 'statistics', term: 'Correlation', definition: 'How closely two things move together, from -1 to +1. Zero means no straight-line relationship, not no relationship at all.', trap: 'Reading a strong correlation as proof that one causes the other.', figure: 'scatter' },
  { id: 'causation', deck: 'statistics', term: 'Correlation is not causation', definition: 'Two series can move together because one causes the other, because something else causes both, or by chance.', example: 'Ice cream sales and drowning both rise in summer. Heat drives both.', trap: 'Recommending an action from a relationship nobody has tested.' },
  { id: 'confounder', deck: 'statistics', term: 'Confounding variable', definition: 'A hidden factor that affects both things you are comparing, creating a relationship that is not real.', example: 'Stores with more staff sell more, because busy stores get more staff.', trap: 'Comparing groups that differ in more than the thing you changed.' },
  { id: 'regression-stats', deck: 'statistics', term: 'Regression', definition: 'Fits a line through data to estimate how much the outcome moves when one input moves, holding the others fixed.', trap: 'Reading coefficients as causes when an important variable is missing.', figure: 'regression' },
  { id: 'coefficient', deck: 'statistics', term: 'Coefficient', definition: 'The estimated effect of a one unit change in an input on the outcome, with the other inputs held constant.', example: 'A price coefficient of -200 means one dollar more cuts about 200 units of demand.', trap: 'Quoting a coefficient without its units or its uncertainty.' },
  { id: 'r-squared-stats', deck: 'statistics', term: 'R-squared', definition: 'The share of the variation in the outcome that the model explains, from 0 to 1.', trap: 'Assuming a high figure means the model will predict new cases well.' },
  { id: 'p-value-stats', deck: 'statistics', term: 'p-value', definition: 'The chance of seeing a result this large if there were really no effect. Small means unlikely to be pure noise.', trap: 'Treating statistical significance as commercial importance.' },
  { id: 'confidence-interval', deck: 'statistics', term: 'Confidence interval', definition: 'A range around an estimate that would contain the true value in most repeated samples.', example: '"42% ± 3 points" means the true share is probably between 39% and 45%.', trap: 'Reporting the single number and dropping the range.' },
  { id: 'margin-error', deck: 'statistics', term: 'Margin of error', definition: 'Half the width of the confidence interval. It shrinks with the square root of the sample, so four times the sample halves it.', trap: 'Comparing two survey results whose gap is inside the margin of error.' },
  { id: 'sample-size-stats', deck: 'statistics', term: 'Sample size', definition: 'How many observations an estimate rests on. Precision improves with the square root of sample size, not in step with it.', trap: 'Generalising from a handful of interviews or a single store.' },
  { id: 'sampling-bias', deck: 'statistics', term: 'Sampling bias', definition: 'The sample is not representative, so the answer is wrong no matter how large it is.', example: 'Surveying satisfaction only among current customers, who by definition stayed.', trap: 'Adding more responses instead of fixing how they are collected.' },
  { id: 'survivorship-stats', deck: 'statistics', term: 'Survivorship bias', definition: 'Looking only at what is left: surviving firms, current customers, funds that still exist.', trap: 'Copying the habits of survivors without studying the failures.' },
  { id: 'selection-effect', deck: 'statistics', term: 'Selection effect', definition: 'Groups differ because of who chose to join, not because of what was done to them, so the comparison is unfair from the start.', example: 'Loyalty programme members spend more partly because heavy buyers join.', trap: 'Crediting a programme with a difference that existed before it started.' },
  { id: 'base-rate-stats', deck: 'statistics', term: 'Base rate', definition: 'How common something is in the population before you look at any specific evidence.', example: 'A test that is 99% accurate still gives mostly false alarms for a disease affecting 1 in 10,000.', trap: 'Judging by how convincing the story sounds and ignoring the underlying rate.' },
  { id: 'conditional-probability', deck: 'statistics', term: 'Conditional probability', definition: 'The chance of something given that something else is true. It is often very different from the unconditional chance.', trap: 'Swapping the direction: the chance of a test flagging illness is not the chance of being ill.' },
  { id: 'expected-value', deck: 'statistics', term: 'Expected value', definition: 'Each outcome multiplied by its probability, summed. It is the long-run average, not what happens once.', example: '30% chance of $100 million and 70% of nothing has an expected value of $30 million.', trap: 'Using it for a one-off bet the company cannot survive losing.' },
  { id: 'ab-test', deck: 'statistics', term: 'A/B test', definition: 'Randomly splitting users between two versions so the only systematic difference is the change you made.', trap: 'Stopping the moment the result looks good, which inflates false positives.' },
  { id: 'control-group', deck: 'statistics', term: 'Control group', definition: 'The group that does not get the change, so you can see what would have happened anyway.', trap: 'Comparing to last year instead, which mixes in every other change.' },
  { id: 'statistical-power', deck: 'statistics', term: 'Statistical power', definition: 'The chance a test detects a real effect of a given size. Small samples miss small effects.', trap: 'Reading "no significant difference" as proof that nothing changed.' },
  { id: 'seasonality-stats', deck: 'statistics', term: 'Seasonality', definition: 'Regular within-year variation, so comparisons must use the same period a year earlier.', trap: 'Calling a normal January dip a trend.' },
  { id: 'moving-average', deck: 'statistics', term: 'Moving average', definition: 'Averages a rolling window to smooth noise so the underlying direction shows.', trap: 'Smoothing so heavily that a genuine turning point disappears.' },
  { id: 'index-stats', deck: 'statistics', term: 'Index', definition: 'Series rebased to 100 at a chosen point so that things of different size can be compared on growth.', trap: 'Comparing two indices with different base years.' },
  { id: 'cohort', deck: 'statistics', term: 'Cohort analysis', definition: 'Tracking one group who joined in the same period over time, so mix changes cannot hide what happened.', example: 'January joiners retained at 60% after three months, April joiners at 40%.', trap: 'Reading a blended average that newer, bigger cohorts dominate.', figure: 'cohort' },
  { id: 'simpsons-stats', deck: 'statistics', term: 'Simpson’s paradox', definition: 'A pattern present in every segment can reverse when segments are combined, usually because the mix changed.', trap: 'Reading a total that hides opposite movements underneath.' },
  { id: 'regression-mean', deck: 'statistics', term: 'Regression to the mean', definition: 'Extreme results tend to be followed by more ordinary ones, with no intervention needed.', example: 'The worst performing stores improve next quarter whether or not you act.', trap: 'Crediting a fix for an improvement that was going to happen anyway.' },

  // ---------- Case maths ----------
  { id: 'pct-change', deck: 'maths', term: 'Percentage change vs percentage points', definition: 'Percentage change divides the change by the old value. Percentage points are the simple difference between two percentages.', example: 'Margin from 10% to 12% is 2 percentage points, which is a 20% increase.', trap: 'Calling a 2 point rise a 2% rise.' },
  { id: 'reverse-pct', deck: 'maths', term: 'Reverse a percentage', definition: 'To undo a rise of x%, divide by (1 + x). To undo a fall, divide by (1 - x).', example: 'A price of $118 including 18% tax is $100 before tax, not $96.8.', trap: 'Subtracting the same percentage you added, which lands somewhere else.' },
  { id: 'percent-of-total', deck: 'maths', term: 'Percentage of what', definition: 'If a part is a share of the total, get the total by dividing the rest by (1 - share).', example: 'Ads are 10% of total revenue and everything else is $280,000, so total is 280,000 ÷ 0.9 = $311,111.', trap: 'Adding 10% to the subtotal when the 10% is a share of the total.' },
  { id: 'cagr-maths', deck: 'maths', term: 'CAGR', short: 'Compound annual growth rate', definition: 'The steady annual rate that turns the start value into the end value: (end ÷ start)^(1 ÷ years) - 1.', example: '100 to 200 over 5 years is about 15% a year, not 20%.', trap: 'Describing a bumpy path as though it grew smoothly.', figure: 'compounding' },
  { id: 'rule-72', deck: 'maths', term: 'Rule of 72', definition: 'Divide 72 by the annual growth rate to get the number of years something takes to double, and divide 72 by the years to get the implied rate.', example: 'At 9% a year, money doubles in about eight years.', trap: 'Using it at very high rates, where it drifts from the true answer.' },
  { id: 'compounding-maths', deck: 'maths', term: 'Compounding', definition: 'Growth stacking on top of previous growth, so rates multiply rather than add. Two years of 10% gives 21%, not 20%.', trap: 'Adding annual rates instead of multiplying the growth factors.', figure: 'compounding' },
  { id: 'growth-bridge', deck: 'maths', term: 'Growth bridge', definition: 'Splits a change into volume, price and mix so you can see which part moved.', example: 'Revenue up 6% = volume up 10%, price down 2%, mix down 2%.', trap: 'Explaining a revenue change without separating price from volume.' },
  { id: 'margin-markup', deck: 'maths', term: 'Margin vs markup', definition: 'Margin divides profit by the selling price. Markup divides the same profit by the cost.', example: 'Cost $80, price $100: margin is 20%, markup is 25%.', trap: 'Quoting markup as though it were margin, which flatters the business.' },
  { id: 'break-even-units-maths', deck: 'maths', term: 'Break-even units', definition: 'Fixed costs ÷ (price - variable cost per unit), rounded up to a whole unit.', trap: 'Using price alone in the denominator, or forgetting to round up.', figure: 'breakeven' },
  { id: 'contribution-maths', deck: 'maths', term: 'Contribution per unit', definition: 'Price less variable cost. Everything above break-even drops through to profit at this rate.', trap: 'Deducting allocated fixed cost, which is not variable.' },
  { id: 'market-size-maths', deck: 'maths', term: 'Market sizing', definition: 'Population, filtered by the shares that qualify, times how often they buy and at what price. Say every assumption aloud.', example: '15 million people × 40% smokers × 20% wanting to quit × 75% who can afford it.', trap: 'Hiding the one assumption that carries most of the answer.' },
  { id: 'per-unit-maths', deck: 'maths', term: 'Normalise per unit', definition: 'Divide by a shared base such as per seat, per store or per hour before comparing two options.', trap: 'Comparing totals from operations of different size.' },
  { id: 'time-base', deck: 'maths', term: 'Match the time base', definition: 'Bring both figures to the same period before dividing: annual over annual, monthly over monthly.', example: 'Annual revenue ÷ monthly orders gives an answer twelve times too high.', trap: 'Mixing a yearly numerator with a monthly denominator.' },
  { id: 'lakh-crore', deck: 'maths', term: 'Millions and billions', definition: 'One billion is 1,000 million. One trillion is 1,000 billion.', example: 'A $150 million raise is $0.15 billion on the balance sheet.', trap: 'Slipping a zero when switching between the two units.' },
  { id: 'fractions', deck: 'maths', term: 'Useful fractions', definition: 'Knowing common fractions as percentages makes division quick: 1/8 is 12.5%, 1/6 about 16.7%, 1/3 about 33.3%, 3/8 is 37.5%.', trap: 'Reaching for long division when a fraction is close enough.' },
  { id: 'round-adjust', deck: 'maths', term: 'Round, then adjust', definition: 'Do the arithmetic with easy round numbers first, then correct for the difference at the end. It is faster and easier to check.', example: '19 × 7 is 20 × 7 = 140, less 7, so 133.', trap: 'Rounding twice in the same direction and drifting off.' },
  { id: 'estimation-anchors', deck: 'maths', term: 'Estimation anchors', definition: 'A few memorised reference points make sizing fast: population, households, working days, hours in a year.', example: 'About 250 working days a year, about 2,000 working hours.', trap: 'Inventing an anchor that is off by an order of magnitude.' },
  { id: 'capacity-maths', deck: 'maths', term: 'Capacity and bottleneck', definition: 'A serial process produces at the rate of its slowest step: the minimum rate times the hours available.', example: 'Three steps at 80, 50 and 70 units an hour produce 50 an hour.', trap: 'Adding capacity across steps instead of taking the minimum.', figure: 'bottleneck' },
  { id: 'utilisation-maths', deck: 'maths', term: 'Utilisation vs capacity', definition: 'Capacity is what an asset could produce. Utilisation is the share actually used.', trap: 'Assuming idle capacity exists when the asset already runs flat out.' },
  { id: 'elasticity-maths', deck: 'maths', term: 'Price elasticity', definition: 'Percentage change in volume divided by percentage change in price. Above 1 means a price cut raises revenue.', example: 'Price down 10%, volume up 15%: elasticity 1.5, so revenue rises.', trap: 'Assuming elasticity without any evidence of how customers responded before.' },
  { id: 'share-shift', deck: 'maths', term: 'Market share arithmetic', definition: 'Share is your sales divided by market sales, so it falls whenever the market grows faster than you do.', example: 'Growing 5% in a market growing 10% cuts a 20% share to 19.1%.', trap: 'Reading falling share as falling sales.' },
  { id: 'annualising', deck: 'maths', term: 'Annualising', definition: 'Scaling a shorter period to a year, which only works if the period is typical.', example: '$20 million a month is $240 million a year, if the month is representative.', trap: 'Annualising a peak season month.' },
  { id: 'per-day', deck: 'maths', term: 'Per day, per hour', definition: 'Converting a large total into a per day, per store or per hour figure makes it tangible, so an error of ten times stands out immediately.', example: '$370 million a year across 300 days and 4 screens is about $31,000 per screen per day.', trap: 'Forgetting that operating days are fewer than calendar days.' },
  { id: 'sanity-range', deck: 'maths', term: 'Sanity range', definition: 'Give an answer as a range with the drivers named, since the inputs were estimates.', trap: 'Quoting an estimate to the dollar and implying precision you do not have.' },
  { id: 'payback-maths', deck: 'maths', term: 'Simple payback', definition: 'Incremental investment divided by the annual net cash benefit it produces, giving the number of years to get the money back.', example: '$8 million ÷ $1.5 million a year is 5.3 years.', trap: 'Using total cost instead of the extra cost over the alternative.' },
  { id: 'weighted-maths', deck: 'maths', term: 'Weighting in case maths', definition: 'Blend segment figures by each segment’s share of the base rather than treating them equally, or the answer leans towards the smallest group.', example: 'Two segments with 80% and 20% of orders blend as 0.8 and 0.2, not 0.5 and 0.5.', trap: 'Averaging segment margins when one segment is far larger.' },

  // ---------- Economics ----------
  { id: 'supply-demand', deck: 'economics', term: 'Supply and demand', definition: 'Price settles where the quantity buyers want equals the quantity sellers offer. Shift either curve and both price and quantity move.', trap: 'Predicting a price change from a demand shift while ignoring how supply reacts.', figure: 'supply-demand' },
  { id: 'elasticity-econ', deck: 'economics', term: 'Elasticity of demand', definition: 'How sensitive volume is to price. Necessities are inelastic; things with close substitutes are elastic.', trap: 'Assuming one elasticity for every customer segment.' },
  { id: 'cross-elasticity', deck: 'economics', term: 'Cross elasticity', definition: 'How demand for one product responds to the price of another. Positive means substitutes, negative means complements.', example: 'Tea and coffee are substitutes; printers and cartridges are complements.', trap: 'Cutting the price of a complement without counting the profit on the pair.' },
  { id: 'marginal-cost', deck: 'economics', term: 'Marginal cost', definition: 'The cost of producing exactly one more unit. It ignores fixed costs already incurred.', example: 'One more passenger on a scheduled flight costs almost nothing.', trap: 'Pricing everything at marginal cost, which never covers fixed costs.' },
  { id: 'marginal-revenue', deck: 'economics', term: 'Marginal revenue', definition: 'The extra revenue from selling one more unit. Profit is maximised where marginal revenue equals marginal cost.', trap: 'Chasing volume past the point where the extra sale costs more than it earns.' },
  { id: 'price-discrimination', deck: 'economics', term: 'Price discrimination', definition: 'Charging different prices to different customers for the same thing, based on what each will pay.', example: 'Advance fares, student tickets, business class.', trap: 'Letting cheap and expensive segments buy from the same channel.' },
  { id: 'consumer-surplus', deck: 'economics', term: 'Consumer surplus', definition: 'The gap between what a customer would have paid and what they did pay. Pricing strategy tries to capture part of it.', trap: 'Capturing so much that customers feel exploited and leave.' },
  { id: 'commodity', deck: 'economics', term: 'Commodity', definition: 'A product buyers see as interchangeable, so price is the main basis of competition and margins stay thin.', trap: 'Investing in brand where customers genuinely cannot tell the difference.' },
  { id: 'perfect-competition', deck: 'economics', term: 'Perfect competition', definition: 'Many sellers of an identical product with free entry, so prices settle near cost and profits stay low.', trap: 'Expecting pricing power in a market that looks like this.' },
  { id: 'oligopoly', deck: 'economics', term: 'Oligopoly', definition: 'A few large players whose decisions depend on each other, so price moves get matched quickly.', trap: 'Modelling a price cut as though rivals will stand still.' },
  { id: 'monopoly', deck: 'economics', term: 'Monopoly and monopsony', definition: 'A monopoly is the only seller; a monopsony is the only buyer. Both give one side power to set terms.', example: 'A single large retailer buying most of a small supplier’s output.', trap: 'Ignoring the regulation that usually follows such power.' },
  { id: 'prisoners-dilemma', deck: 'economics', term: 'Prisoner’s dilemma', definition: 'Each player gains by undercutting, yet both end up worse off than if they had held. It explains price wars.', trap: 'Starting a discount war you cannot fund longer than the rival can.' },
  { id: 'externality', deck: 'economics', term: 'Externality', definition: 'A cost or benefit falling on someone outside the transaction, such as pollution or a vaccination.', trap: 'Assuming the market price reflects the full cost to society.' },
  { id: 'inflation', deck: 'economics', term: 'Inflation', definition: 'A general rise in prices, so the same money buys less. Compare figures in real terms to strip it out.', example: '5% revenue growth with 6% inflation is a real fall.', trap: 'Celebrating nominal growth that inflation more than explains.' },
  { id: 'interest-rate', deck: 'economics', term: 'Interest rate', definition: 'The price of money over time. Higher rates make borrowing costlier and future cash worth less today.', trap: 'Modelling a long project as if today’s rate lasts for ever.' },
  { id: 'exchange-rate', deck: 'economics', term: 'Exchange rate', definition: 'The price of one currency in another. A weaker home currency helps exporters and hurts importers.', trap: 'Ignoring currency when costs and revenues are earned in different ones.' },
  { id: 'gdp', deck: 'economics', term: 'GDP', short: 'Gross domestic product', definition: 'The value of everything produced in a country in a period, and the usual proxy for the size of an economy.', trap: 'Comparing countries without adjusting for population or price levels.' },
  { id: 'tariff', deck: 'economics', term: 'Tariff', definition: 'A tax on imports. It protects local producers and raises prices for local buyers.', trap: 'Modelling only the benefit to the protected industry.' },
  { id: 'price-cap', deck: 'economics', term: 'Price regulation', definition: 'A ceiling or formula set by a regulator, common in utilities, telecom and healthcare.', trap: 'Building a pricing plan a regulator would never allow.' },
  { id: 'switching-econ', deck: 'economics', term: 'Substitutes and complements', definition: 'Substitutes replace each other; complements are used together. Pricing one affects demand for the other.', trap: 'Optimising a product in isolation when it sells alongside another.' },
  { id: 'scale-econ', deck: 'economics', term: 'Minimum efficient scale', definition: 'The output level at which unit cost stops falling much. Below it, a competitor with more volume wins on cost.', trap: 'Entering a scale industry with a plant far below it.' },
  { id: 'learning-econ', deck: 'economics', term: 'Marginal thinking', definition: 'Decisions are made at the margin: what changes if you do a bit more or a bit less, not what the average looks like.', trap: 'Using average cost to decide whether to accept one extra order.' },
  // ---------- Operations ----------
  { id: 'bottleneck-ops', deck: 'operations', term: 'Bottleneck', definition: 'The slowest step in a process. It sets the output of the whole line, so only improvements there raise throughput.', example: 'Three machines at 80, 50 and 70 units an hour give a line rate of 50.', trap: 'Speeding up a step that is not the constraint, which just builds inventory in front of it.', figure: 'bottleneck' },
  { id: 'throughput', deck: 'operations', term: 'Throughput', definition: 'Units completed per unit of time. It is the measure that matters, rather than how busy each machine looks.', trap: 'Judging a line by machine utilisation rather than finished output.' },
  { id: 'cycle-time', deck: 'operations', term: 'Cycle time', definition: 'Time between one finished unit and the next. It is the inverse of the production rate.', example: 'A cycle time of 30 seconds is 120 units an hour.', trap: 'Confusing it with lead time, which covers the whole wait a customer sees.' },
  { id: 'lead-time', deck: 'operations', term: 'Lead time', definition: 'Total elapsed time from order to delivery, including waiting, processing and transport.', trap: 'Reporting production time only and ignoring the queue before it.' },
  { id: 'takt-time', deck: 'operations', term: 'Takt time', definition: 'Available working time divided by customer demand: the pace the line must run to keep up.', example: '420 usable minutes and 840 orders means one unit every 30 seconds.', trap: 'Setting the pace from capacity instead of from demand.' },
  { id: 'wip', deck: 'operations', term: 'Work in progress', definition: 'Units started but not finished. It is cash tied up, and it hides problems between steps.', trap: 'Letting inventory pile up to keep every station busy.' },
  { id: 'littles-law', deck: 'operations', term: 'Little’s law', definition: 'Work in progress equals throughput times lead time. Cut work in progress and lead time falls with it.', example: '100 items in the system at 20 a day means five days of lead time.', trap: 'Trying to cut lead time while queues keep growing.' },
  { id: 'utilisation-ops', deck: 'operations', term: 'Utilisation', definition: 'The share of available time an asset is actually producing. Running above roughly 85% makes queues grow quickly.', trap: 'Targeting 100%, which leaves no room for variability and lengthens waits.' },
  { id: 'oee', deck: 'operations', term: 'OEE', short: 'Overall equipment effectiveness', definition: 'Availability times performance times quality: one number for how much of theoretical output you actually get.', trap: 'Chasing the score rather than fixing the biggest of its three parts.' },
  { id: 'changeover', deck: 'operations', term: 'Changeover time', definition: 'Time lost switching a line from one product to another. It is why short runs cost more per unit.', trap: 'Adding product variety without counting the changeovers it creates.' },
  { id: 'inventory-turns', deck: 'operations', term: 'Inventory turns', definition: 'Cost of goods sold divided by average inventory: how many times a year the stock sells through.', example: 'Six turns means about two months of stock on hand.', trap: 'Cutting stock so hard that stockouts cost more than the saving.' },
  { id: 'safety-stock', deck: 'operations', term: 'Safety stock', definition: 'Extra inventory held as a buffer against uncertain demand or unreliable supply, sized from how variable both are.', trap: 'Sizing it by feel rather than by variability and the promised service level.' },
  { id: 'reorder-point', deck: 'operations', term: 'Reorder point', definition: 'The stock level that triggers a new order: expected demand during the lead time, plus safety stock.', trap: 'Ignoring that a longer lead time raises the reorder point.' },
  { id: 'eoq', deck: 'operations', term: 'Economic order quantity', definition: 'The order size that balances the cost of placing orders against the cost of holding stock, so total cost is lowest.', trap: 'Ordering large quantities for the discount while ignoring the storage and obsolescence cost.' },
  { id: 'jit', deck: 'operations', term: 'Just in time', definition: 'Materials arrive as needed, so little inventory is held. It is efficient and fragile in equal measure.', trap: 'Running it on a supply chain with unreliable lead times.' },
  { id: 'lean', deck: 'operations', term: 'Lean', definition: 'Removing work that does not add value for the customer: waiting, moving, rework, overproduction.', trap: 'Cutting resources and calling it lean, which is just a smaller version of the same process.' },
  { id: 'six-sigma', deck: 'operations', term: 'Six sigma', definition: 'A method for reducing variation, so output stays inside the tolerance customers accept.', trap: 'Applying heavy statistical work to a process nobody has mapped yet.' },
  { id: 'yield-ops', deck: 'operations', term: 'Yield and scrap', definition: 'Yield is the share of good output; scrap and rework are what fails. Both raise the real cost per good unit.', example: '90% yield means each good unit carries the cost of 1.11 started units.', trap: 'Costing a unit using started volume instead of good output.' },
  { id: 'service-level', deck: 'operations', term: 'Service level', definition: 'The share of demand met from stock or within a promised time. Higher levels cost more inventory or capacity.', trap: 'Promising a service level the network cannot fund.' },
  { id: 'capacity-planning', deck: 'operations', term: 'Capacity planning', definition: 'Matching capacity to expected demand over time, deciding whether to lead demand, lag it, or flex with overtime.', trap: 'Building for peak demand that occurs a few days a year.' },
  { id: 'last-mile', deck: 'operations', term: 'Last mile', definition: 'The final delivery to the customer. It is the most expensive leg because drops are small and scattered.', trap: 'Sizing delivery cost from long haul rates per kilometre.' },
  { id: 'third-party-logistics', deck: 'operations', term: 'Third party logistics', definition: 'Outsourcing warehousing or transport, converting fixed cost into variable cost and giving up some control.', trap: 'Outsourcing a step that is core to the customer experience.' },

  // ---------- Customers ----------
  { id: 'segmentation', deck: 'marketing', term: 'Segmentation', definition: 'Splitting customers into groups that behave differently, so each can get a different offer or price.', example: 'Business travellers book late and pay more; leisure travellers book early and shop around.', trap: 'Segmenting by what is easy to measure rather than by what changes behaviour.' },
  { id: 'targeting', deck: 'marketing', term: 'Targeting', definition: 'Choosing which segments to serve, based on size, growth, willingness to pay and how well you can serve them.', trap: 'Trying to serve everyone and being preferred by no one.' },
  { id: 'positioning', deck: 'marketing', term: 'Positioning', definition: 'The place you want to occupy in a customer’s mind relative to alternatives, in one sentence.', trap: 'Claiming a position the product cannot deliver.' },
  { id: 'value-proposition', deck: 'marketing', term: 'Value proposition', definition: 'What the customer gets, who it is for, and why it beats the alternative they would otherwise choose.', trap: 'Listing features instead of the problem solved.' },
  { id: 'brand-equity', deck: 'marketing', term: 'Brand equity', definition: 'The extra a customer will pay, or the preference they show, because of the name on the product.', trap: 'Spending on awareness when the problem is distribution or price.' },
  { id: 'purchase-funnel', deck: 'marketing', term: 'Purchase funnel', definition: 'Awareness, consideration, trial, purchase, repeat. Comparing your drop-offs with rivals shows where the loss is.', example: '90% aware but 20% considering points to a perception problem, not reach.', trap: 'Adding traffic at the top when the leak is at checkout.', figure: 'funnel' },
  { id: 'cac', deck: 'marketing', term: 'Customer acquisition cost', short: 'CAC', definition: 'Total sales and marketing spend divided by the customers that spending won, including salaries and discounts, not just advertising.', trap: 'Counting only advertising and leaving out sales salaries and discounts.' },
  { id: 'ltv', deck: 'marketing', term: 'Lifetime value', definition: 'Expected profit from a customer over the whole relationship: margin per period times expected lifetime.', example: '$500 a month margin with a two-year life is $12,000.', trap: 'Using revenue rather than margin, which overstates it.' },
  { id: 'churn-marketing', deck: 'marketing', term: 'Churn rate', definition: 'Share of customers leaving in a period. Average lifetime is roughly one divided by the churn rate.', example: '5% monthly churn implies an average life of about 20 months.', trap: 'Hiding churn behind gross additions.' },
  { id: 'retention', deck: 'marketing', term: 'Retention', definition: 'The share who stay, the mirror of churn. Small gains compound because they apply every period.', trap: 'Buying retention with discounts that cost more than the margin saved.' },
  { id: 'nps', deck: 'marketing', term: 'Net promoter score', definition: 'Share of promoters less share of detractors from a willingness-to-recommend question.', trap: 'Treating a score change as proof of a behaviour change.' },
  { id: 'penetration', deck: 'marketing', term: 'Penetration', definition: 'Share of a target group that buys at all, as distinct from how often buyers purchase.', trap: 'Trying to raise frequency when most of the market has never tried the product.' },
  { id: 'frequency', deck: 'marketing', term: 'Frequency and basket', definition: 'Revenue per customer is how often they buy times how much they spend each time.', trap: 'Growing basket size with bundles that simply pull forward future purchases.' },
  { id: 'cross-sell', deck: 'marketing', term: 'Cross-sell and upsell', definition: 'Cross-sell adds a different product; upsell moves the customer to a more expensive version.', trap: 'Pushing either before the first product has delivered value.' },
  { id: 'price-ladder', deck: 'marketing', term: 'Price ladder', definition: 'A range of versions at different prices, so customers sort themselves by willingness to pay.', trap: 'Setting the gaps so wide that the cheapest option takes everyone.' },
  { id: 'promotion-discount', deck: 'marketing', term: 'Promotion vs discount', definition: 'A promotion is temporary and targeted; a discount lowers the reference price customers expect.', trap: 'Running so many promotions that nobody buys at full price.' },
  { id: 'channel-mix', deck: 'marketing', term: 'Channel mix', definition: 'The split of sales across routes to market, each with a different cost to serve and margin.', trap: 'Comparing channel revenue without netting off commissions and returns.' },
  { id: 'share-of-wallet', deck: 'marketing', term: 'Share of wallet', definition: 'The share of a customer’s spending in the category that comes to you, rather than share of all customers.', trap: 'Chasing new customers when existing ones spend most of their budget elsewhere.' },
  { id: 'stickiness', deck: 'marketing', term: 'Stickiness', definition: 'How embedded the product is in a customer’s routine, usually measured by usage frequency or depth.', trap: 'Reading a sign-up as engagement.' },
  { id: 'word-of-mouth', deck: 'marketing', term: 'Referral', definition: 'Customers acquired by existing ones. Referred customers usually cost less and stay longer.', trap: 'Paying for referrals that would have happened anyway.' },

  // ---------- Sector terms ----------
  { id: 'arpu', deck: 'industry', term: 'ARPU', short: 'Average revenue per user', definition: 'Revenue divided by subscribers for a period. It is the core telecom gauge of pricing power.', trap: 'Reading a fall as lost customers when it usually means cheaper plans.' },
  { id: 'load-factor', deck: 'industry', term: 'Passenger load factor', definition: 'The share of available seats that were actually filled on a flight, the standard measure of how well capacity is sold.', example: '180 passengers in a 200 seat aircraft is 90%.', trap: 'Assuming a full flight is profitable: the fare matters as much as the seat.' },
  { id: 'ask-rpk', deck: 'industry', term: 'ASK and RPK', definition: 'Available seat kilometres measure the capacity offered; revenue passenger kilometres measure what was sold.', trap: 'Comparing airlines by passengers alone, which ignores distance flown.' },
  { id: 'rask-cask', deck: 'industry', term: 'RASK and CASK', definition: 'Revenue and cost per available seat kilometre. The gap between them is the airline’s margin.', trap: 'Cutting cost per seat kilometre by adding seats that go unsold.' },
  { id: 'mro', deck: 'industry', term: 'MRO', short: 'Maintenance, repair and overhaul', definition: 'Keeping aircraft airworthy. In the sector report it ran at 13% to 15% of airline revenue.', trap: 'Treating maintenance as discretionary cost rather than a safety requirement.' },
  { id: 'non-aero', deck: 'industry', term: 'Non-aeronautical revenue', definition: 'Airport income from retail, advertising, parking and property rather than from airlines.', trap: 'Forgetting it depends on how long passengers dwell and who they are.' },
  { id: 'take-rate', deck: 'industry', term: 'Take rate', definition: 'The share of each transaction a marketplace keeps as commission, which is its revenue from the sale rather than the sale itself.', example: '8% on $1,000 of goods is $80 of platform revenue.', trap: 'Confusing platform revenue with the value of goods sold on it.' },
  { id: 'gmv', deck: 'industry', term: 'GMV', short: 'Gross merchandise value', definition: 'Total value of goods sold through a platform before returns, discounts and commission.', trap: 'Quoting it as revenue, which it is not.' },
  { id: 'aov', deck: 'industry', term: 'Average order value', definition: 'Revenue divided by number of orders. It decides whether delivery cost per order is affordable.', trap: 'Lifting it with discounts that cost more than the extra basket earns.' },
  { id: 'cart-abandonment', deck: 'industry', term: 'Cart abandonment', definition: 'Share of shoppers who add items then leave without buying, a gauge of friction at checkout.', trap: 'Blaming price when delivery cost or a slow checkout is the real cause.' },
  { id: 'clv-industry', deck: 'industry', term: 'Repeat rate', definition: 'Share of customers who buy again within a period. It separates a real habit from a one-off promotion.', trap: 'Judging a cohort before enough time has passed for a repeat purchase.' },
  { id: 'otd', deck: 'industry', term: 'On-time delivery', definition: 'Share of orders delivered within the promised window. It drives repeat purchase and returns.', trap: 'Measuring dispatch instead of what the customer experiences.' },
  { id: 'teledensity', deck: 'industry', term: 'Tele-density', definition: 'Telephone connections per 100 people, split urban and rural to show where growth remains.', trap: 'Reading connections as people, since many subscribers hold two SIM cards.' },
  { id: 'spectrum', deck: 'industry', term: 'Spectrum', definition: 'Licensed radio frequency an operator buys to carry traffic: a large, upfront and unavoidable cost.', trap: 'Leaving licence and spectrum charges out of the cost base.' },
  { id: 'churn-telecom', deck: 'industry', term: 'Subscriber churn', definition: 'Share of subscribers leaving in a period. With easy number portability, small differences compound fast.', trap: 'Adding subscribers to mask churn instead of fixing its cause.' },
  { id: 'nim', deck: 'industry', term: 'Net interest margin', short: 'NIM', definition: 'Interest earned on loans less interest paid on deposits, as a share of lending assets. It is a bank’s core spread.', example: '$100 lent at 10% funded at 6% gives a 4% margin, before costs and defaults.', trap: 'Using the headline loan rate instead of the spread over funding.' },
  { id: 'casa', deck: 'industry', term: 'CASA ratio', short: 'Current and savings account', definition: 'Share of deposits held in current and savings accounts, which pay little interest, so a high ratio means cheap funding.', trap: 'Chasing deposits at rates that destroy the margin they fund.' },
  { id: 'npa', deck: 'industry', term: 'Non-performing asset', short: 'NPA', definition: 'A loan where repayments have stopped, usually past 90 days. It stops earning and needs provisioning.', trap: 'Growing the loan book fast enough to make the bad-loan ratio look small.' },
  { id: 'cost-income', deck: 'industry', term: 'Cost to income ratio', definition: 'Operating costs divided by income: the standard efficiency gauge for banks and insurers.', trap: 'Improving it by cutting the service that generates income.' },
  { id: 'same-store', deck: 'industry', term: 'Same-store sales', definition: 'Growth from stores open in both periods, stripping out openings and closures.', trap: 'Reading total sales growth as proof the existing stores are healthy.' },
  { id: 'footfall', deck: 'industry', term: 'Footfall and conversion', definition: 'Footfall is visitors; conversion is the share who buy. Revenue is footfall times conversion times basket.', trap: 'Spending to raise footfall when conversion is the weak link.' },
  { id: 'sales-per-sqft', deck: 'industry', term: 'Sales per square foot', definition: 'Revenue divided by selling area, the standard way to compare stores of different sizes.', trap: 'Comparing formats with very different ranges and rents.' },
  { id: 'shrinkage', deck: 'industry', term: 'Shrinkage', definition: 'Stock lost to theft, damage or error, measured against sales. Small percentages matter on thin retail margins.', trap: 'Treating it as unavoidable rather than as a process problem.' },
  { id: 'revpar', deck: 'industry', term: 'RevPAR', short: 'Revenue per available room', definition: 'Occupancy times average daily rate: it captures both how full a hotel is and what it charges.', example: '70% occupancy at $6,000 gives RevPAR of $4,200.', trap: 'Buying occupancy with discounts that lower RevPAR overall.' },
  { id: 'adr', deck: 'industry', term: 'Average daily rate', definition: 'Room revenue divided by the number of rooms sold: the price side of the hotel equation, separate from how full the hotel is.', trap: 'Judging performance on rate alone while rooms sit empty.' },
  { id: 'mrr-arr', deck: 'industry', term: 'MRR and ARR', short: 'Monthly and annual recurring revenue', definition: 'Subscription revenue normalised to a month or a year, excluding one-off fees.', trap: 'Including setup fees, which are not recurring.' },
  { id: 'nrr', deck: 'industry', term: 'Net revenue retention', definition: 'Revenue this year from last year’s customers, including upgrades and losses. Above 100% means the base grows without new customers.', trap: 'Reading it as a substitute for winning new customers.' },
  { id: 'patent-cliff', deck: 'industry', term: 'Patent cliff', definition: 'The sharp revenue fall when a drug loses exclusivity and generic versions arrive.', trap: 'Forecasting a branded drug beyond the date its protection ends.' },
  { id: 'generic', deck: 'industry', term: 'Generic drug', definition: 'A copy of an off-patent medicine with the same active ingredient, sold far cheaper and competing on cost and distribution.', trap: 'Expecting brand pricing power in a generics business.' },
  { id: 'prescription-otc', deck: 'industry', term: 'Prescription vs over the counter', definition: 'Prescription products are chosen by doctors; over-the-counter products are chosen by the shopper. The marketing route differs completely.', trap: 'Planning consumer advertising for a product only doctors can prescribe.' },
  { id: 'distribution-reach', deck: 'industry', term: 'Distribution reach', definition: 'The share of relevant outlets that stock the product, the ceiling on what consumer demand can convert into sales.', trap: 'Advertising a product that shoppers cannot find on the shelf.' },
  { id: 'primary-secondary', deck: 'industry', term: 'Primary and secondary sales', definition: 'Primary sales go from company to distributor; secondary sales go from distributor to retailer. Only the second reflects real demand.', trap: 'Booking primary sales into a channel already full of stock.' },
  { id: 'capacity-utilisation-ind', deck: 'industry', term: 'Capacity utilisation', definition: 'Output as a share of what the plant could produce. In heavy industry it drives unit cost more than anything else.', trap: 'Cutting price to fill a plant when the extra volume loses money.' },
  { id: 'ppa', deck: 'industry', term: 'Power purchase agreement', short: 'PPA', definition: 'A long-term contract to buy power at an agreed price, which makes revenue predictable for a generator.', trap: 'Valuing a generator on spot prices when its output is contracted for years.' },
  { id: 'cost-per-km', deck: 'industry', term: 'Cost per kilometre', definition: 'Total operating cost divided by distance covered, the standard unit in logistics and transport.', trap: 'Comparing routes without adjusting for load factor and empty running.' },
  // ---------- GRE vocabulary ----------
  { id: 'v-abate', deck: 'vocab', term: 'Abate', short: 'verb', definition: 'To become less intense or widespread, or to make something less so.', example: 'The storm abated by morning, so the flights resumed.', trap: 'Not the same as abet, which means to help someone do wrong.' },
  { id: 'v-aberrant', deck: 'vocab', term: 'Aberrant', short: 'adjective', definition: 'Departing from what is normal or expected, usually in a way that is unwelcome.', example: 'One aberrant reading did not change the overall pattern.', trap: 'It describes a deviation, not something merely rare or excellent.' },
  { id: 'v-abeyance', deck: 'vocab', term: 'Abeyance', short: 'noun', definition: 'A state of temporary suspension, where something is paused rather than cancelled.', example: 'The policy was held in abeyance until the review finished.', trap: 'It means paused, not abandoned.' },
  { id: 'v-abscond', deck: 'vocab', term: 'Abscond', short: 'verb', definition: 'To leave quickly and secretly, usually to escape trouble or after taking something.', example: 'The treasurer absconded with the funds.', trap: 'It carries the idea of fleeing wrongdoing, not just departing.' },
  { id: 'v-abstemious', deck: 'vocab', term: 'Abstemious', short: 'adjective', definition: 'Sparing or restrained, especially in eating and drinking.', example: 'An abstemious diet of plain food and no wine.', trap: 'Abstemious is moderation by choice; abstinent is going without entirely.' },
  { id: 'v-admonish', deck: 'vocab', term: 'Admonish', short: 'verb', definition: 'To warn or reprimand someone firmly but not harshly.', example: 'The referee admonished the captain for arguing.', trap: 'Milder than condemn, and it often includes advice.' },
  { id: 'v-aggrandize', deck: 'vocab', term: 'Aggrandize', short: 'verb', definition: 'To increase power, wealth or reputation, often beyond what is deserved.', example: 'He rewrote the report to aggrandize his own role.', trap: 'It usually implies inflating, not honest growth.' },
  { id: 'v-alacrity', deck: 'vocab', term: 'Alacrity', short: 'noun', definition: 'Brisk and cheerful readiness to do something.', example: 'She accepted the assignment with alacrity.', trap: 'It is eagerness plus speed, not speed alone.' },
  { id: 'v-amalgamate', deck: 'vocab', term: 'Amalgamate', short: 'verb', definition: 'To combine separate things into one whole.', example: 'The two departments amalgamated into a single team.', trap: 'Stronger than coordinate: the parts stop being separate.' },
  { id: 'v-ambivalent', deck: 'vocab', term: 'Ambivalent', short: 'adjective', definition: 'Holding two opposing feelings about the same thing at once.', example: 'He felt ambivalent about the promotion, glad and uneasy together.', trap: 'Ambivalent is mixed feelings; ambiguous is unclear meaning; indifferent is no feeling at all.' },
  { id: 'v-ameliorate', deck: 'vocab', term: 'Ameliorate', short: 'verb', definition: 'To make a bad situation better.', example: 'Shade trees ameliorated the heat in the courtyard.', trap: 'It improves conditions; it does not cure or remove the cause.' },
  { id: 'v-anachronism', deck: 'vocab', term: 'Anachronism', short: 'noun', definition: 'Something placed in the wrong period of time.', example: 'A wristwatch in a film about ancient Rome is an anachronism.', trap: 'It is about time, not about being merely old-fashioned in taste.' },
  { id: 'v-anodyne', deck: 'vocab', term: 'Anodyne', short: 'adjective', definition: 'Unlikely to offend or excite anyone, and so rather bland.', example: 'The statement was anodyne enough to please both sides.', trap: 'It suggests deliberately inoffensive, not simply calm.' },
  { id: 'v-anomaly', deck: 'vocab', term: 'Anomaly', short: 'noun', definition: 'Something that breaks the usual pattern or rule.', example: 'A single loss in a decade of wins is an anomaly.', trap: 'One anomaly is an exception, not yet evidence of a new trend.' },
  { id: 'v-antipathy', deck: 'vocab', term: 'Antipathy', short: 'noun', definition: 'A deep, settled dislike that has hardened over time.', example: 'His antipathy to meetings was well known.', trap: 'Stronger and more permanent than mere annoyance.' },
  { id: 'v-apathy', deck: 'vocab', term: 'Apathy', short: 'noun', definition: 'A lack of interest, enthusiasm or concern.', example: 'Voter apathy kept turnout low.', trap: 'Apathy is not caring; antipathy is actively disliking.' },
  { id: 'v-apocryphal', deck: 'vocab', term: 'Apocryphal', short: 'adjective', definition: 'Widely repeated but probably untrue.', example: 'The story about the founder sleeping in the office is apocryphal.', trap: 'It means doubtful in origin, not simply false.' },
  { id: 'v-approbation', deck: 'vocab', term: 'Approbation', short: 'noun', definition: 'Approval or praise, often formal.', example: 'The plan won the approbation of the board.', trap: 'Approbation is approval; appropriation is taking something for your own use.' },
  { id: 'v-arduous', deck: 'vocab', term: 'Arduous', short: 'adjective', definition: 'Demanding sustained effort, tiring and difficult.', example: 'An arduous climb in thin air.', trap: 'It describes effort required, not danger.' },
  { id: 'v-artless', deck: 'vocab', term: 'Artless', short: 'adjective', definition: 'Without cunning or pretence, natural and sincere.', example: 'Her artless answer disarmed the panel.', trap: 'It is a compliment about honesty, not a criticism of skill.' },
  { id: 'v-ascetic', deck: 'vocab', term: 'Ascetic', short: 'adjective', definition: 'Severely plain and self-denying, avoiding comfort and pleasure.', example: 'An ascetic room with a bed and nothing else.', trap: 'Ascetic is self-denying; aesthetic concerns beauty.' },
  { id: 'v-assuage', deck: 'vocab', term: 'Assuage', short: 'verb', definition: 'To soothe or relieve an unpleasant feeling.', example: 'The apology assuaged their anger.', trap: 'It eases a feeling rather than solving the underlying problem.' },
  { id: 'v-attenuate', deck: 'vocab', term: 'Attenuate', short: 'verb', definition: 'To reduce the strength, force or effect of something.', example: 'Distance attenuates the signal.', trap: 'It weakens; it does not eliminate.' },
  { id: 'v-audacious', deck: 'vocab', term: 'Audacious', short: 'adjective', definition: 'Boldly daring, sometimes to the point of rudeness.', example: 'An audacious bid for a company ten times its size.', trap: 'It can be admiring or critical, depending on context.' },
  { id: 'v-austere', deck: 'vocab', term: 'Austere', short: 'adjective', definition: 'Severe and plain, without comfort or decoration.', example: 'The austere hall had bare walls and hard benches.', trap: 'Of people it means stern; of places it means undecorated.' },
  { id: 'v-aver', deck: 'vocab', term: 'Aver', short: 'verb', definition: 'To state firmly that something is true.', example: 'She averred that the records were complete.', trap: 'It means assert confidently, not prove.' },
  { id: 'v-banal', deck: 'vocab', term: 'Banal', short: 'adjective', definition: 'So ordinary and overused that it is boring.', example: 'A banal speech of safe compliments.', trap: 'Banal means dull through overuse; benign means harmless.' },
  { id: 'v-belie', deck: 'vocab', term: 'Belie', short: 'verb', definition: 'To give a false impression of something, or to show a claim to be untrue.', example: 'Her calm voice belied her nerves.', trap: 'It does not mean to lie about; the subject is the misleading thing itself.' },
  { id: 'v-beleaguer', deck: 'vocab', term: 'Beleaguer', short: 'verb', definition: 'To surround with difficulties or with troops, leaving little room to act.', example: 'The beleaguered manager faced complaints from every side.', trap: 'It suggests being hemmed in, not merely busy.' },
  { id: 'v-bolster', deck: 'vocab', term: 'Bolster', short: 'verb', definition: 'To support or strengthen something.', example: 'New evidence bolstered the argument.', trap: 'It reinforces something existing rather than creating it.' },
  { id: 'v-bombastic', deck: 'vocab', term: 'Bombastic', short: 'adjective', definition: 'High-sounding but with little meaning behind it.', example: 'A bombastic address full of grand phrases and no plan.', trap: 'It criticises the style as empty, not the volume.' },
  { id: 'v-burgeon', deck: 'vocab', term: 'Burgeon', short: 'verb', definition: 'To grow or expand rapidly, usually from a small beginning.', example: 'Demand burgeoned once the price fell.', trap: 'It implies fast growth from a small start.' },
  { id: 'v-buttress', deck: 'vocab', term: 'Buttress', short: 'verb', definition: 'To support or reinforce, literally or in argument.', example: 'He buttressed the claim with three studies.', trap: 'Close to bolster, but with a sense of structural support.' },
  { id: 'v-cacophony', deck: 'vocab', term: 'Cacophony', short: 'noun', definition: 'A harsh, jarring mixture of sounds.', example: 'A cacophony of horns at the junction.', trap: 'Its opposite is euphony, a pleasing sound.' },
  { id: 'v-capricious', deck: 'vocab', term: 'Capricious', short: 'adjective', definition: 'Changing suddenly and without good reason.', example: 'A capricious manager who reversed decisions weekly.', trap: 'Capricious is unpredictable by whim; mercurial stresses swings of mood.' },
  { id: 'v-castigate', deck: 'vocab', term: 'Castigate', short: 'verb', definition: 'To criticise someone severely and openly for a fault.', example: 'The report castigated the regulator for inaction.', trap: 'Much harsher than admonish.' },
  { id: 'v-caustic', deck: 'vocab', term: 'Caustic', short: 'adjective', definition: 'Bitingly sarcastic, or chemically able to burn.', example: 'A caustic review that spared nobody.', trap: 'In writing it describes tone, not volume.' },
  { id: 'v-chicanery', deck: 'vocab', term: 'Chicanery', short: 'noun', definition: 'The use of clever but dishonest tricks.', example: 'The contract was won through legal chicanery.', trap: 'It implies deception, not mere cleverness.' },
  { id: 'v-circumscribe', deck: 'vocab', term: 'Circumscribe', short: 'verb', definition: 'To restrict something within limits.', example: 'The new rules circumscribed what auditors could accept.', trap: 'It limits scope; it does not ban outright.' },
  { id: 'v-circumspect', deck: 'vocab', term: 'Circumspect', short: 'adjective', definition: 'Cautious, considering every consequence before acting.', example: 'A circumspect reply that committed to nothing.', trap: 'Circumspect is careful; circumscribed is limited.' },
  { id: 'v-coalesce', deck: 'vocab', term: 'Coalesce', short: 'verb', definition: 'To come together to form one group or mass.', example: 'The factions coalesced around one candidate.', trap: 'It suggests merging gradually and naturally.' },
  { id: 'v-cogent', deck: 'vocab', term: 'Cogent', short: 'adjective', definition: 'Clear, logical and convincing.', example: 'A cogent case for closing the plant.', trap: 'It praises the reasoning, not the delivery.' },
  { id: 'v-complaisant', deck: 'vocab', term: 'Complaisant', short: 'adjective', definition: 'Willing to please others and go along with them.', example: 'A complaisant colleague who agreed to every change.', trap: 'Complaisant is eager to please; complacent is smugly satisfied.' },
  { id: 'v-conciliatory', deck: 'vocab', term: 'Conciliatory', short: 'adjective', definition: 'Intended to calm anger and win goodwill.', example: 'A conciliatory email after a tense meeting.', trap: 'It describes intent to soothe, not surrender.' },
  { id: 'v-condone', deck: 'vocab', term: 'Condone', short: 'verb', definition: 'To accept or overlook behaviour that is wrong.', example: 'Ignoring the breach would condone it.', trap: 'Condone is to overlook; condemn is the opposite.' },
  { id: 'v-contentious', deck: 'vocab', term: 'Contentious', short: 'adjective', definition: 'Likely to cause argument, or fond of arguing.', example: 'A contentious clause held up the deal.', trap: 'It can describe the issue or the person.' },
  { id: 'v-contrite', deck: 'vocab', term: 'Contrite', short: 'adjective', definition: 'Genuinely sorry for a wrong you have done.', example: 'A contrite apology, offered without excuses.', trap: 'It implies real remorse, not just regret at being caught.' },
  { id: 'v-convoluted', deck: 'vocab', term: 'Convoluted', short: 'adjective', definition: 'So complex and twisting that it is hard to follow.', example: 'A convoluted ownership structure across four countries.', trap: 'Complicated is not always bad; convoluted always suggests needlessly so.' },
  { id: 'v-corroborate', deck: 'vocab', term: 'Corroborate', short: 'verb', definition: 'To support a statement with further evidence.', example: 'Two witnesses corroborated the account.', trap: 'It adds support; it does not prove alone.' },
  { id: 'v-craven', deck: 'vocab', term: 'Craven', short: 'adjective', definition: 'Shamefully cowardly, in a way that invites contempt.', example: 'A craven silence when someone had to speak.', trap: 'Stronger and more contemptuous than timid.' },
  { id: 'v-credulous', deck: 'vocab', term: 'Credulous', short: 'adjective', definition: 'Too ready to believe things, and so easily fooled.', example: 'A credulous audience believed the promised returns.', trap: 'Credulous describes the believer; credible describes the claim.' },
  { id: 'v-cursory', deck: 'vocab', term: 'Cursory', short: 'adjective', definition: 'Done quickly and without attention to detail.', example: 'A cursory glance at the accounts.', trap: 'It describes lack of care, not lack of time available.' },
  { id: 'v-daunt', deck: 'vocab', term: 'Daunt', short: 'verb', definition: 'To make someone lose confidence before they begin.', example: 'The scale of the backlog daunted the new team.', trap: 'Dauntless means the opposite: not discouraged at all.' },
  { id: 'v-decorum', deck: 'vocab', term: 'Decorum', short: 'noun', definition: 'Behaviour that fits the occasion, polite and proper.', example: 'They kept decorum even as the argument sharpened.', trap: 'It concerns conduct, not decoration.' },
  { id: 'v-deference', deck: 'vocab', term: 'Deference', short: 'noun', definition: 'Polite respect that yields to someone else’s judgement.', example: 'Out of deference to the founder, the name stayed.', trap: 'Deference is respect; difference is a distinction.' },
  { id: 'v-denigrate', deck: 'vocab', term: 'Denigrate', short: 'verb', definition: 'To criticise unfairly in order to damage a reputation.', example: 'He denigrated rivals rather than defending his own record.', trap: 'It implies unfairness, unlike honest criticism.' },
  { id: 'v-deride', deck: 'vocab', term: 'Deride', short: 'verb', definition: 'To mock someone or something with open contempt.', example: 'Critics derided the forecast as fantasy.', trap: 'Harsher than doubt or dismiss: it includes ridicule.' },
  { id: 'v-desultory', deck: 'vocab', term: 'Desultory', short: 'adjective', definition: 'Jumping from one thing to another without plan or enthusiasm.', example: 'A desultory search through old files.', trap: 'It describes aimlessness, not slowness.' },
  { id: 'v-diatribe', deck: 'vocab', term: 'Diatribe', short: 'noun', definition: 'A long, angry attack in speech or writing.', example: 'The letter turned into a diatribe against regulators.', trap: 'A diatribe attacks; a treatise explains.' },
  { id: 'v-didactic', deck: 'vocab', term: 'Didactic', short: 'adjective', definition: 'Intended to teach, sometimes in a preachy way.', example: 'A didactic novel with a lesson on every page.', trap: 'It often carries a mild criticism of moralising.' },
  { id: 'v-diffident', deck: 'vocab', term: 'Diffident', short: 'adjective', definition: 'Lacking confidence and therefore holding back.', example: 'A diffident speaker who apologised before starting.', trap: 'Diffident is shy; indifferent is uninterested.' },
  { id: 'v-dilatory', deck: 'vocab', term: 'Dilatory', short: 'adjective', definition: 'Slow to act, often deliberately, in order to delay.', example: 'Dilatory replies pushed the deadline past the quarter.', trap: 'It suggests delay as a tactic, not mere lateness.' },
  { id: 'v-disabuse', deck: 'vocab', term: 'Disabuse', short: 'verb', definition: 'To free someone from a mistaken belief.', example: 'The data disabused them of the idea that price was the problem.', trap: 'It corrects a belief; it does not insult anyone.' },
  { id: 'v-discrete', deck: 'vocab', term: 'Discrete', short: 'adjective', definition: 'Separate and distinct, as individual units.', example: 'Three discrete stages, each with its own owner.', trap: 'Discrete is separate; discreet is careful not to attract attention.' },
  { id: 'v-disingenuous', deck: 'vocab', term: 'Disingenuous', short: 'adjective', definition: 'Pretending to be sincere while hiding the real motive.', example: 'A disingenuous question designed to trap the speaker.', trap: 'It is milder than lying but still dishonest.' },
  { id: 'v-disparage', deck: 'vocab', term: 'Disparage', short: 'verb', definition: 'To speak of someone or something as unimportant.', example: 'She never disparaged the work of her predecessor.', trap: 'Disparage belittles; disparate means different in kind.' },
  { id: 'v-disparate', deck: 'vocab', term: 'Disparate', short: 'adjective', definition: 'So different in kind that comparison is difficult.', example: 'Disparate systems that store the same customer twice.', trap: 'It means fundamentally different, not merely unequal.' },
  { id: 'v-dissemble', deck: 'vocab', term: 'Dissemble', short: 'verb', definition: 'To hide your true feelings or intentions.', example: 'He dissembled, praising a plan he meant to block.', trap: 'Dissemble is to conceal; disassemble is to take apart.' },
  { id: 'v-disseminate', deck: 'vocab', term: 'Disseminate', short: 'verb', definition: 'To spread information widely, so that it reaches many people.', example: 'The findings were disseminated to every branch.', trap: 'It concerns distribution, not creation.' },
  { id: 'v-dogmatic', deck: 'vocab', term: 'Dogmatic', short: 'adjective', definition: 'Insisting on your views as if they cannot be questioned.', example: 'A dogmatic refusal to consider the pilot results.', trap: 'It criticises the rigidity, not the belief itself.' },
  { id: 'v-ebullient', deck: 'vocab', term: 'Ebullient', short: 'adjective', definition: 'Overflowing with cheerful energy.', example: 'An ebullient host who never sat down.', trap: 'It describes visible high spirits, not mere happiness.' },
  { id: 'v-eclectic', deck: 'vocab', term: 'Eclectic', short: 'adjective', definition: 'Drawing ideas from many different sources.', example: 'An eclectic method borrowed from design and statistics.', trap: 'It means broad in sources, not disorganised.' },
  { id: 'v-efficacy', deck: 'vocab', term: 'Efficacy', short: 'noun', definition: 'The power of something to produce the result intended.', example: 'Trials measured the efficacy of the treatment.', trap: 'Efficacy is whether it works; efficiency is at what cost.' },
  { id: 'v-effrontery', deck: 'vocab', term: 'Effrontery', short: 'noun', definition: 'Bold rudeness with no sense of shame.', example: 'He had the effrontery to ask for a bonus after the loss.', trap: 'Stronger than confidence: it implies insolence.' },
  { id: 'v-elicit', deck: 'vocab', term: 'Elicit', short: 'verb', definition: 'To draw out a response or information from someone.', example: 'The question elicited an unexpected admission.', trap: 'Elicit is to draw out; illicit means illegal.' },
  { id: 'v-empirical', deck: 'vocab', term: 'Empirical', short: 'adjective', definition: 'Based on observation or experiment rather than theory alone.', example: 'Empirical results from twelve stores, not a model.', trap: 'Empirical means observed, which is not the same as correct.' },
  { id: 'v-emulate', deck: 'vocab', term: 'Emulate', short: 'verb', definition: 'To copy someone in order to match or beat them.', example: 'Rivals tried to emulate its delivery times.', trap: 'It implies ambition, not flattery.' },
  { id: 'v-enervate', deck: 'vocab', term: 'Enervate', short: 'verb', definition: 'To drain energy and leave something weakened.', example: 'The long delay enervated the team.', trap: 'It means to weaken, which is the opposite of energise.' },
  { id: 'v-engender', deck: 'vocab', term: 'Engender', short: 'verb', definition: 'To give rise to a feeling or situation.', example: 'Clear rules engender trust.', trap: 'It creates conditions rather than forcing an outcome.' },
  { id: 'v-ephemeral', deck: 'vocab', term: 'Ephemeral', short: 'adjective', definition: 'Lasting a very short time before disappearing.', example: 'An ephemeral spike in traffic after the article.', trap: 'Ephemeral is brief; eternal is its opposite.' },
  { id: 'v-equanimity', deck: 'vocab', term: 'Equanimity', short: 'noun', definition: 'Calmness and balance, especially under pressure.', example: 'She took the criticism with equanimity.', trap: 'It is composure, not indifference.' },
  { id: 'v-equivocate', deck: 'vocab', term: 'Equivocate', short: 'verb', definition: 'To speak vaguely on purpose, to avoid committing.', example: 'He equivocated when asked for a date.', trap: 'Equivocate is deliberate vagueness; hesitate is just pausing.' },
  { id: 'v-erudite', deck: 'vocab', term: 'Erudite', short: 'adjective', definition: 'Showing deep learning gained from study.', example: 'An erudite footnote on medieval trade.', trap: 'It praises knowledge, not intelligence as such.' },
  { id: 'v-eschew', deck: 'vocab', term: 'Eschew', short: 'verb', definition: 'To deliberately avoid something on principle.', example: 'The firm eschews short-term trading.', trap: 'It implies a choice, not an inability.' },
  { id: 'v-esoteric', deck: 'vocab', term: 'Esoteric', short: 'adjective', definition: 'Understood by only a small group with special knowledge.', example: 'An esoteric debate about accounting treatment.', trap: 'Esoteric is specialised; exotic is foreign or unusual.' },
  { id: 'v-evanescent', deck: 'vocab', term: 'Evanescent', short: 'adjective', definition: 'Vanishing quickly and gradually, the way mist fades.', example: 'The evanescent advantage lasted one season.', trap: 'Close to ephemeral, with a stronger sense of fading away.' },
  { id: 'v-exacerbate', deck: 'vocab', term: 'Exacerbate', short: 'verb', definition: 'To make a bad situation worse.', example: 'The price rise exacerbated the shortage.', trap: 'Exacerbate worsens; exasperate irritates a person.' },
  { id: 'v-exculpate', deck: 'vocab', term: 'Exculpate', short: 'verb', definition: 'To clear someone of blame or of a charge against them.', example: 'The audit exculpated the finance team.', trap: 'Exculpate clears; inculpate implicates.' },
  { id: 'v-exigent', deck: 'vocab', term: 'Exigent', short: 'adjective', definition: 'Urgent and demanding immediate attention.', example: 'Exigent circumstances justified the overnight decision.', trap: 'Exigent is urgent; exiguous means scanty.' },
  { id: 'v-extant', deck: 'vocab', term: 'Extant', short: 'adjective', definition: 'Still in existence, not lost or destroyed.', example: 'The only extant copy sits in the archive.', trap: 'Extant means surviving; extinct is the opposite.' },
  { id: 'v-extol', deck: 'vocab', term: 'Extol', short: 'verb', definition: 'To praise highly and publicly.', example: 'The report extolled the benefits of the merger.', trap: 'Extol is to praise; extort is to take by threat.' },
  { id: 'v-facetious', deck: 'vocab', term: 'Facetious', short: 'adjective', definition: 'Joking about something that deserves seriousness.', example: 'A facetious remark during a safety briefing.', trap: 'It implies bad timing, not just humour.' },
  { id: 'v-fastidious', deck: 'vocab', term: 'Fastidious', short: 'adjective', definition: 'Very attentive to detail, and hard to please.', example: 'A fastidious editor who checked every figure twice.', trap: 'It can praise care or criticise fussiness.' },
  { id: 'v-fatuous', deck: 'vocab', term: 'Fatuous', short: 'adjective', definition: 'Silly and pointless, with an air of confidence.', example: 'A fatuous suggestion to double sales by Friday.', trap: 'Stronger than foolish: it suggests self-satisfied nonsense.' },
  { id: 'v-felicitous', deck: 'vocab', term: 'Felicitous', short: 'adjective', definition: 'Well chosen and pleasingly apt.', example: 'A felicitous phrase that ended the argument.', trap: 'It means apt, not merely lucky.' },
  { id: 'v-flout', deck: 'vocab', term: 'Flout', short: 'verb', definition: 'To break a rule openly and with contempt.', example: 'Drivers flouted the parking ban.', trap: 'Flout is to defy; flaunt is to display showily.' },
  { id: 'v-foment', deck: 'vocab', term: 'Foment', short: 'verb', definition: 'To stir up trouble or strong feeling.', example: 'The rumour fomented unrest among suppliers.', trap: 'It is used for unrest and discontent, rarely for good things.' },
  { id: 'v-forestall', deck: 'vocab', term: 'Forestall', short: 'verb', definition: 'To act first in order to prevent something.', example: 'They cut prices to forestall a new entrant.', trap: 'It prevents by acting early, not by reacting.' },
  { id: 'v-garrulous', deck: 'vocab', term: 'Garrulous', short: 'adjective', definition: 'Talking too much, especially about trivial things.', example: 'A garrulous neighbour who narrated the whole street.', trap: 'Garrulous is rambling; eloquent is well spoken.' },
  { id: 'v-germane', deck: 'vocab', term: 'Germane', short: 'adjective', definition: 'Directly relevant to the matter at hand.', example: 'Only germane objections were taken.', trap: 'It means relevant, not merely true.' },
  { id: 'v-gregarious', deck: 'vocab', term: 'Gregarious', short: 'adjective', definition: 'Enjoying the company of others and seeking it out.', example: 'A gregarious salesperson who knew every client.', trap: 'It is about sociability, not charm.' },
  { id: 'v-guile', deck: 'vocab', term: 'Guile', short: 'noun', definition: 'Clever but deceitful cunning, used to get an advantage.', example: 'He won the negotiation by guile rather than strength.', trap: 'Guileless means honest and open, not stupid.' },
  { id: 'v-hackneyed', deck: 'vocab', term: 'Hackneyed', short: 'adjective', definition: 'Worn out from overuse, and so no longer effective.', example: 'A hackneyed metaphor about journeys.', trap: 'Close to banal, with a stronger sense of repetition.' },
  { id: 'v-harangue', deck: 'vocab', term: 'Harangue', short: 'noun or verb', definition: 'A long, forceful lecture aimed at someone.', example: 'The coach delivered a harangue at half time.', trap: 'It is aggressive and one-sided, unlike a discussion.' },
  { id: 'v-iconoclast', deck: 'vocab', term: 'Iconoclast', short: 'noun', definition: 'A person who attacks cherished beliefs and institutions.', example: 'An iconoclast who questioned every industry assumption.', trap: 'It describes challenging beliefs, not simply being unusual.' },
  { id: 'v-idiosyncratic', deck: 'vocab', term: 'Idiosyncratic', short: 'adjective', definition: 'Peculiar to one person, in a distinctive way.', example: 'An idiosyncratic filing system only she could use.', trap: 'It means individual, not wrong.' },
  { id: 'v-imminent', deck: 'vocab', term: 'Imminent', short: 'adjective', definition: 'About to happen very soon, with little or no warning left.', example: 'An imminent announcement kept everyone at their desks.', trap: 'Imminent is soon; eminent is distinguished; immanent is inherent.' },
  { id: 'v-impassive', deck: 'vocab', term: 'Impassive', short: 'adjective', definition: 'Showing no emotion at all, whatever is happening inside.', example: 'The negotiator stayed impassive as the offer rose.', trap: 'It describes the outward face, not the inner feeling.' },
  { id: 'v-impecunious', deck: 'vocab', term: 'Impecunious', short: 'adjective', definition: 'Having little or no money, usually for a long period.', example: 'An impecunious student living on library coffee.', trap: 'It is a formal word for poor, not for careless with money.' },
  { id: 'v-imperious', deck: 'vocab', term: 'Imperious', short: 'adjective', definition: 'Commanding in an arrogant, expect-to-be-obeyed way.', example: 'An imperious wave sent the waiter away.', trap: 'Imperious is domineering; imperial relates to an empire.' },
  { id: 'v-impervious', deck: 'vocab', term: 'Impervious', short: 'adjective', definition: 'Unable to be affected or penetrated.', example: 'Impervious to criticism, he filed the same plan again.', trap: 'It can be physical or emotional.' },
  { id: 'v-implacable', deck: 'vocab', term: 'Implacable', short: 'adjective', definition: 'Impossible to calm down or satisfy.', example: 'An implacable opponent of the merger.', trap: 'It means unappeasable, not merely persistent.' },
  { id: 'v-inchoate', deck: 'vocab', term: 'Inchoate', short: 'adjective', definition: 'Just begun and not yet fully formed.', example: 'An inchoate plan with no dates or owners.', trap: 'It means undeveloped, not chaotic.' },
  { id: 'v-incipient', deck: 'vocab', term: 'Incipient', short: 'adjective', definition: 'In an early stage and beginning to appear.', example: 'Incipient cracks in the supplier relationship.', trap: 'Incipient is beginning; insipid is dull and tasteless.' },
  { id: 'v-incongruous', deck: 'vocab', term: 'Incongruous', short: 'adjective', definition: 'Out of place next to its surroundings.', example: 'An incongruous neon sign on a stone chapel.', trap: 'It concerns fit, not quality.' },
  { id: 'v-indolent', deck: 'vocab', term: 'Indolent', short: 'adjective', definition: 'Habitually avoiding effort, out of preference rather than tiredness.', example: 'An indolent afternoon with nothing finished.', trap: 'It is a formal word for lazy, not slow.' },
  { id: 'v-ineffable', deck: 'vocab', term: 'Ineffable', short: 'adjective', definition: 'Too great or intense to be put into words.', example: 'The ineffable relief when the system came back.', trap: 'It means beyond description, not forbidden to say.' },
  { id: 'v-ingenuous', deck: 'vocab', term: 'Ingenuous', short: 'adjective', definition: 'Innocent and trusting, without suspicion.', example: 'An ingenuous question that exposed the problem.', trap: 'Ingenuous is naive and sincere; ingenious is clever.' },
  { id: 'v-inimical', deck: 'vocab', term: 'Inimical', short: 'adjective', definition: 'Harmful to something, or openly hostile.', example: 'Constant reorganisation is inimical to good work.', trap: 'Inimical is harmful; inimitable means impossible to copy.' },
  { id: 'v-innocuous', deck: 'vocab', term: 'Innocuous', short: 'adjective', definition: 'Harmless and unlikely to offend.', example: 'An innocuous comment that somehow started an argument.', trap: 'It means harmless, not unimportant.' },
  { id: 'v-intractable', deck: 'vocab', term: 'Intractable', short: 'adjective', definition: 'Very hard to control or solve.', example: 'An intractable dispute over territory.', trap: 'Intractable is hard to manage; tractable is easily handled.' },
  { id: 'v-intransigent', deck: 'vocab', term: 'Intransigent', short: 'adjective', definition: 'Refusing to compromise at all.', example: 'An intransigent union and an intransigent board.', trap: 'It is about refusing to move, not about being wrong.' },
  { id: 'v-inundate', deck: 'vocab', term: 'Inundate', short: 'verb', definition: 'To overwhelm with a flood of things.', example: 'Support was inundated after the outage.', trap: 'It suggests volume beyond capacity.' },
  { id: 'v-inveterate', deck: 'vocab', term: 'Inveterate', short: 'adjective', definition: 'Having a long-established habit that is unlikely to change.', example: 'An inveterate note-taker with forty notebooks.', trap: 'It describes long habit, not necessarily a bad one.' },
  { id: 'v-irascible', deck: 'vocab', term: 'Irascible', short: 'adjective', definition: 'Easily made angry, often over small things.', example: 'An irascible editor who hated small talk.', trap: 'It is a standing tendency, not a single outburst.' },
  { id: 'v-laconic', deck: 'vocab', term: 'Laconic', short: 'adjective', definition: 'Using very few words, often to the point of seeming blunt.', example: 'A laconic reply: "Noted."', trap: 'Laconic is brief; taciturn is habitually silent.' },
  { id: 'v-lassitude', deck: 'vocab', term: 'Lassitude', short: 'noun', definition: 'Physical or mental weariness with no energy to act.', example: 'A general lassitude settled over the project.', trap: 'It is tiredness plus lack of will, not sleepiness.' },
  { id: 'v-laud', deck: 'vocab', term: 'Laud', short: 'verb', definition: 'To praise, especially publicly.', example: 'The chairman lauded the retiring engineer.', trap: 'Laudable means deserving praise; laudatory means giving it.' },
  { id: 'v-levity', deck: 'vocab', term: 'Levity', short: 'noun', definition: 'Humour or lightness where seriousness is expected.', example: 'A moment of levity broke the tension.', trap: 'Levity is lightness; brevity is shortness.' },
  { id: 'v-loquacious', deck: 'vocab', term: 'Loquacious', short: 'adjective', definition: 'Very talkative, especially about things of little consequence.', example: 'A loquacious guide who filled every silence.', trap: 'It is neutral about quality, unlike garrulous.' },
  { id: 'v-magnanimous', deck: 'vocab', term: 'Magnanimous', short: 'adjective', definition: 'Generous, especially towards a rival or someone defeated.', example: 'A magnanimous tribute to the outgoing competitor.', trap: 'It implies generosity from a position of strength.' },
  { id: 'v-malleable', deck: 'vocab', term: 'Malleable', short: 'adjective', definition: 'Easily shaped, whether a metal or a person’s views.', example: 'A malleable process that each team adapted.', trap: 'For people it can imply being easily influenced.' },
  { id: 'v-maverick', deck: 'vocab', term: 'Maverick', short: 'noun', definition: 'An independent-minded person who refuses to follow the group.', example: 'The maverick analyst who kept the sell rating.', trap: 'It suggests independence, not necessarily rebellion for its own sake.' },
  { id: 'v-mendacious', deck: 'vocab', term: 'Mendacious', short: 'adjective', definition: 'Lying, or in the habit of lying.', example: 'A mendacious account of what the audit found.', trap: 'Mendacious is untruthful; mendicant means begging.' },
  { id: 'v-mercurial', deck: 'vocab', term: 'Mercurial', short: 'adjective', definition: 'Changing mood quickly and unpredictably.', example: 'A mercurial client, delighted one week and furious the next.', trap: 'It stresses mood swings; capricious stresses whim.' },
  { id: 'v-misanthrope', deck: 'vocab', term: 'Misanthrope', short: 'noun', definition: 'Someone who dislikes people in general.', example: 'The misanthrope in the corner office answered no emails.', trap: 'Misanthrope dislikes people; philanthropist gives to them.' },
  { id: 'v-mitigate', deck: 'vocab', term: 'Mitigate', short: 'verb', definition: 'To make something bad less severe.', example: 'Insurance mitigated the loss.', trap: 'Mitigate reduces harm; militate against means to work against.' },
  { id: 'v-mollify', deck: 'vocab', term: 'Mollify', short: 'verb', definition: 'To calm someone’s anger, usually with words or a concession.', example: 'A refund mollified the customer.', trap: 'Mollify soothes a person; mitigate softens a thing.' },
  { id: 'v-munificent', deck: 'vocab', term: 'Munificent', short: 'adjective', definition: 'Extremely generous in giving, on a scale beyond what is expected.', example: 'A munificent donation funded the whole wing.', trap: 'It describes the scale of the gift, not the motive.' },
  { id: 'v-nascent', deck: 'vocab', term: 'Nascent', short: 'adjective', definition: 'Just coming into existence and beginning to show promise.', example: 'A nascent market with three small players.', trap: 'Nascent is starting; latent is present but hidden.' },
  { id: 'v-nebulous', deck: 'vocab', term: 'Nebulous', short: 'adjective', definition: 'Vague and without clear shape.', example: 'A nebulous strategy that nobody could act on.', trap: 'It means unclear, not complicated.' },
  { id: 'v-obdurate', deck: 'vocab', term: 'Obdurate', short: 'adjective', definition: 'Stubbornly refusing to change, especially to soften.', example: 'The landlord was obdurate about the rent.', trap: 'It adds hardness of heart to plain stubbornness.' },
  { id: 'v-obfuscate', deck: 'vocab', term: 'Obfuscate', short: 'verb', definition: 'To make something unclear on purpose.', example: 'The footnotes obfuscated the size of the write-off.', trap: 'It is deliberate, unlike simply confusing writing.' },
  { id: 'v-obsequious', deck: 'vocab', term: 'Obsequious', short: 'adjective', definition: 'Excessively eager to please those in authority.', example: 'An obsequious reply agreeing with every word.', trap: 'It is flattery that has become embarrassing.' },
  { id: 'v-obtuse', deck: 'vocab', term: 'Obtuse', short: 'adjective', definition: 'Slow to understand, sometimes wilfully.', example: 'He was being obtuse about a very clear instruction.', trap: 'Obtuse is dull of mind; abstruse is hard to understand.' },
  { id: 'v-officious', deck: 'vocab', term: 'Officious', short: 'adjective', definition: 'Interfering with unwanted advice or authority.', example: 'An officious clerk who rejected forms on a technicality.', trap: 'Officious is meddling; official means authorised.' },
  { id: 'v-onerous', deck: 'vocab', term: 'Onerous', short: 'adjective', definition: 'Involving a heavy burden of effort or obligation.', example: 'Onerous reporting duties for small suppliers.', trap: 'It describes burden, not difficulty of understanding.' },
  { id: 'v-opprobrium', deck: 'vocab', term: 'Opprobrium', short: 'noun', definition: 'Harsh public criticism and the disgrace it brings.', example: 'The decision drew opprobrium from every quarter.', trap: 'It combines criticism with shame.' },
  { id: 'v-ostentatious', deck: 'vocab', term: 'Ostentatious', short: 'adjective', definition: 'Showy in a way designed to impress.', example: 'An ostentatious headquarters for a company losing money.', trap: 'It criticises display, not expense as such.' },
  { id: 'v-palliate', deck: 'vocab', term: 'Palliate', short: 'verb', definition: 'To ease symptoms without curing the cause.', example: 'Discounts palliated the complaints for a month.', trap: 'It treats effects, not causes.' },
  { id: 'v-panacea', deck: 'vocab', term: 'Panacea', short: 'noun', definition: 'A supposed cure for every problem.', example: 'Automation is not a panacea for weak processes.', trap: 'Usually used to say no such cure exists.' },
  { id: 'v-paragon', deck: 'vocab', term: 'Paragon', short: 'noun', definition: 'A perfect example of a quality.', example: 'A paragon of patience during the handover.', trap: 'Paragon is a model of excellence; paradigm is a pattern or framework.' },
  { id: 'v-paucity', deck: 'vocab', term: 'Paucity', short: 'noun', definition: 'A shortage of something needed.', example: 'A paucity of reliable data on rural demand.', trap: 'It means too little, not none.' },
  { id: 'v-pedantic', deck: 'vocab', term: 'Pedantic', short: 'adjective', definition: 'Overly concerned with small rules and details.', example: 'A pedantic argument about the title of the appendix.', trap: 'It criticises the fuss, not the accuracy.' },
  { id: 'v-penchant', deck: 'vocab', term: 'Penchant', short: 'noun', definition: 'A strong liking or habitual preference.', example: 'A penchant for starting projects and leaving them.', trap: 'It is a tendency, not an ability.' },
  { id: 'v-perfidy', deck: 'vocab', term: 'Perfidy', short: 'noun', definition: 'Betrayal of trust by someone who was relied upon.', example: 'The leak was seen as perfidy by the whole team.', trap: 'Stronger than dishonesty: it breaks a trust.' },
  { id: 'v-perfunctory', deck: 'vocab', term: 'Perfunctory', short: 'adjective', definition: 'Done as a duty, with minimum effort or interest.', example: 'A perfunctory nod and no questions.', trap: 'Perfunctory is going through the motions; cursory is hasty.' },
  { id: 'v-pernicious', deck: 'vocab', term: 'Pernicious', short: 'adjective', definition: 'Causing harm gradually and almost unnoticed.', example: 'The pernicious effect of small, constant delays.', trap: 'The harm is slow and subtle, not sudden.' },
  { id: 'v-perspicacious', deck: 'vocab', term: 'Perspicacious', short: 'adjective', definition: 'Quick to notice and understand what others miss.', example: 'A perspicacious reader spotted the inconsistency.', trap: 'Perspicacious is sharp-sighted; perspicuous means clearly expressed.' },
  { id: 'v-phlegmatic', deck: 'vocab', term: 'Phlegmatic', short: 'adjective', definition: 'Calm and unexcitable, even under provocation.', example: 'A phlegmatic response to a furious email.', trap: 'It suggests steady temperament, not laziness.' },
  { id: 'v-pithy', deck: 'vocab', term: 'Pithy', short: 'adjective', definition: 'Short and full of meaning, with nothing wasted.', example: 'A pithy summary in two lines.', trap: 'Pithy is brief and pointed; wordy is the opposite.' },
  { id: 'v-placate', deck: 'vocab', term: 'Placate', short: 'verb', definition: 'To make someone less angry by doing something for them.', example: 'A quick fix placated the biggest customer.', trap: 'Placate acts to calm; mollify often uses words.' },
  { id: 'v-platitude', deck: 'vocab', term: 'Platitude', short: 'noun', definition: 'A flat, overused remark offered as if it were insightful.', example: 'The speech offered platitudes about teamwork.', trap: 'It is the remark itself; banal describes the quality.' },
  { id: 'v-polemic', deck: 'vocab', term: 'Polemic', short: 'noun', definition: 'A strong written or spoken attack on an opinion.', example: 'A polemic against quarterly reporting.', trap: 'It argues one side deliberately, unlike an analysis.' },
  { id: 'v-pragmatic', deck: 'vocab', term: 'Pragmatic', short: 'adjective', definition: 'Dealing with things practically rather than by theory.', example: 'A pragmatic compromise that shipped on time.', trap: 'It means practical, not unprincipled.' },
  { id: 'v-precarious', deck: 'vocab', term: 'Precarious', short: 'adjective', definition: 'Unstable and likely to fail or fall.', example: 'A precarious cash position two weeks from payroll.', trap: 'It describes instability, not certainty of failure.' },
  { id: 'v-preclude', deck: 'vocab', term: 'Preclude', short: 'verb', definition: 'To make something impossible in advance.', example: 'The clause precludes any refund after delivery.', trap: 'Preclude prevents; postpone delays.' },
  { id: 'v-prescient', deck: 'vocab', term: 'Prescient', short: 'adjective', definition: 'Showing knowledge of what will happen before it does.', example: 'A prescient memo written a year before the crash.', trap: 'It means foresight, not luck.' },
  { id: 'v-prevaricate', deck: 'vocab', term: 'Prevaricate', short: 'verb', definition: 'To avoid giving a straight answer.', example: 'He prevaricated rather than admit the delay.', trap: 'Prevaricate is evasive speech; procrastinate is delaying action.' },
  { id: 'v-probity', deck: 'vocab', term: 'Probity', short: 'noun', definition: 'Complete honesty and strong moral principles.', example: 'A reputation for probity kept the audit short.', trap: 'It is about integrity, not skill.' },
  { id: 'v-prodigal', deck: 'vocab', term: 'Prodigal', short: 'adjective', definition: 'Spending money or resources wastefully.', example: 'Prodigal marketing spending with no measurement.', trap: 'Prodigal is wasteful; prodigious means enormous.' },
  { id: 'v-prodigious', deck: 'vocab', term: 'Prodigious', short: 'adjective', definition: 'Remarkably large or impressive.', example: 'A prodigious amount of work in one quarter.', trap: 'It describes scale, not waste.' },
  { id: 'v-profligate', deck: 'vocab', term: 'Profligate', short: 'adjective', definition: 'Recklessly extravagant with money or resources.', example: 'Profligate use of cloud credits over the weekend.', trap: 'It is stronger than prodigal and implies recklessness.' },
  { id: 'v-prolific', deck: 'vocab', term: 'Prolific', short: 'adjective', definition: 'Producing a great deal, and doing so consistently.', example: 'A prolific author with thirty books.', trap: 'It refers to quantity, not quality.' },
  { id: 'v-propitious', deck: 'vocab', term: 'Propitious', short: 'adjective', definition: 'Giving a good chance of success, favourable.', example: 'A propitious moment to raise capital.', trap: 'It describes conditions, not the outcome.' },
  { id: 'v-prosaic', deck: 'vocab', term: 'Prosaic', short: 'adjective', definition: 'Plain and ordinary, lacking imagination.', example: 'A prosaic explanation: someone unplugged it.', trap: 'It means dull, not incorrect.' },
  { id: 'v-quiescent', deck: 'vocab', term: 'Quiescent', short: 'adjective', definition: 'Inactive or dormant for the time being.', example: 'A quiescent competitor that suddenly raised money.', trap: 'It means temporarily still, not finished.' },
  { id: 'v-quixotic', deck: 'vocab', term: 'Quixotic', short: 'adjective', definition: 'Idealistic to the point of being impractical.', example: 'A quixotic plan to rebuild the network in a month.', trap: 'It suggests hopeless idealism, not simple ambition.' },
  { id: 'v-recalcitrant', deck: 'vocab', term: 'Recalcitrant', short: 'adjective', definition: 'Resisting authority or control, and hard to handle.', example: 'A recalcitrant supplier who ignored the schedule.', trap: 'It implies active resistance, not passive delay.' },
  { id: 'v-recondite', deck: 'vocab', term: 'Recondite', short: 'adjective', definition: 'Dealing with a subject so deep that few understand it.', example: 'A recondite paper on settlement mechanics.', trap: 'Close to esoteric, with an emphasis on difficulty.' },
  { id: 'v-refute', deck: 'vocab', term: 'Refute', short: 'verb', definition: 'To prove a statement wrong with evidence.', example: 'The trial refuted the earlier claim.', trap: 'Refute requires proof; deny is merely saying no.' },
  { id: 'v-relegate', deck: 'vocab', term: 'Relegate', short: 'verb', definition: 'To move something to a lower or less important position.', example: 'The issue was relegated to an appendix.', trap: 'Relegate demotes; delegate hands over a task.' },
  { id: 'v-reticent', deck: 'vocab', term: 'Reticent', short: 'adjective', definition: 'Unwilling to say much about your thoughts or feelings.', example: 'Reticent about the reasons for leaving.', trap: 'Reticent is reserved in speech; reluctant is unwilling to act.' },
  { id: 'v-sagacious', deck: 'vocab', term: 'Sagacious', short: 'adjective', definition: 'Showing good judgement and practical wisdom.', example: 'A sagacious decision to keep cash aside.', trap: 'It praises judgement, not knowledge.' },
  { id: 'v-salient', deck: 'vocab', term: 'Salient', short: 'adjective', definition: 'Most noticeable and important.', example: 'The salient point was the missing deadline.', trap: 'It means standing out, not merely relevant.' },
  { id: 'v-sanction', deck: 'vocab', term: 'Sanction', short: 'noun or verb', definition: 'A word with two opposite senses: official approval, or a penalty imposed.', example: 'The board sanctioned the plan, while regulators imposed sanctions on the trade.', trap: 'Only the sentence tells you which sense is meant.' },
  { id: 'v-sanguine', deck: 'vocab', term: 'Sanguine', short: 'adjective', definition: 'Cheerfully optimistic, especially in a difficult situation.', example: 'Sanguine about the recovery despite a weak quarter.', trap: 'It means hopeful, despite sounding like it relates to blood.' },
  { id: 'v-scrupulous', deck: 'vocab', term: 'Scrupulous', short: 'adjective', definition: 'Very careful to do what is right, down to the details.', example: 'Scrupulous record keeping made the audit easy.', trap: 'Unscrupulous means willing to act dishonestly.' },
  { id: 'v-soporific', deck: 'vocab', term: 'Soporific', short: 'adjective', definition: 'Tending to make you sleepy, whether a drug or a dull speech.', example: 'A soporific presentation after lunch.', trap: 'It describes the effect on the listener, not the speaker.' },
  { id: 'v-specious', deck: 'vocab', term: 'Specious', short: 'adjective', definition: 'Seeming right at first, but actually wrong.', example: 'A specious argument that confused correlation with cause.', trap: 'Specious looks true but is not; spurious is simply fake.' },
  { id: 'v-spurious', deck: 'vocab', term: 'Spurious', short: 'adjective', definition: 'False or fake in origin, however convincing it looks.', example: 'A spurious correlation between two unrelated series.', trap: 'Spurious is false in origin; specious is plausible but flawed.' },
  { id: 'v-staid', deck: 'vocab', term: 'Staid', short: 'adjective', definition: 'Serious, settled and rather dull.', example: 'A staid institution that had not changed its logo in fifty years.', trap: 'It suggests unadventurous, not unfriendly.' },
  { id: 'v-stymie', deck: 'vocab', term: 'Stymie', short: 'verb', definition: 'To block or frustrate progress.', example: 'Missing approvals stymied the launch.', trap: 'It means obstructed, not cancelled.' },
  { id: 'v-substantiate', deck: 'vocab', term: 'Substantiate', short: 'verb', definition: 'To support a claim with evidence.', example: 'The invoice substantiated the expense.', trap: 'Substantiate provides proof; state merely asserts.' },
  { id: 'v-supercilious', deck: 'vocab', term: 'Supercilious', short: 'adjective', definition: 'Behaving as though others are beneath you.', example: 'A supercilious tone in every reply to juniors.', trap: 'It is arrogance shown in manner, not in words alone.' },
  { id: 'v-superfluous', deck: 'vocab', term: 'Superfluous', short: 'adjective', definition: 'More than is needed, and so unnecessary.', example: 'Three superfluous approval steps.', trap: 'It means excess, not harmful.' },
  { id: 'v-surfeit', deck: 'vocab', term: 'Surfeit', short: 'noun', definition: 'An excessive amount of something, often to the point of discomfort.', example: 'A surfeit of dashboards and a shortage of decisions.', trap: 'It is too much, unlike sufficiency.' },
  { id: 'v-sycophant', deck: 'vocab', term: 'Sycophant', short: 'noun', definition: 'Someone who flatters powerful people for personal gain.', example: 'A circle of sycophants agreed with every suggestion.', trap: 'It names the person; obsequious describes the behaviour.' },
  { id: 'v-tacit', deck: 'vocab', term: 'Tacit', short: 'adjective', definition: 'Understood without being said.', example: 'Tacit approval to keep going.', trap: 'Tacit is unspoken; explicit is stated.' },
  { id: 'v-taciturn', deck: 'vocab', term: 'Taciturn', short: 'adjective', definition: 'Saying very little by habit, even when others expect a reply.', example: 'A taciturn colleague who answered in single words.', trap: 'Taciturn is a lasting trait; laconic describes a particular style.' },
  { id: 'v-temerity', deck: 'vocab', term: 'Temerity', short: 'noun', definition: 'Boldness that shows disrespect for risk or rank.', example: 'She had the temerity to question the chief executive.', trap: 'Temerity is reckless nerve; timidity is its opposite.' },
  { id: 'v-tenuous', deck: 'vocab', term: 'Tenuous', short: 'adjective', definition: 'Very weak or slight, easily broken.', example: 'A tenuous link between the two events.', trap: 'It means weak, not false.' },
  { id: 'v-torpor', deck: 'vocab', term: 'Torpor', short: 'noun', definition: 'A state of sluggish inactivity.', example: 'Summer torpor settled over the office.', trap: 'It is physical and mental slowness, not sleep.' },
  { id: 'v-tortuous', deck: 'vocab', term: 'Tortuous', short: 'adjective', definition: 'Full of twists and turns, literally or in argument.', example: 'A tortuous approval path through four committees.', trap: 'Tortuous is winding; torturous is painful.' },
  { id: 'v-trenchant', deck: 'vocab', term: 'Trenchant', short: 'adjective', definition: 'Sharp and effective in expression.', example: 'A trenchant critique that changed the plan.', trap: 'It praises incisiveness, not harshness.' },
  { id: 'v-truculent', deck: 'vocab', term: 'Truculent', short: 'adjective', definition: 'Eager to argue or fight, and quick to take offence.', example: 'A truculent response to a routine question.', trap: 'It is aggressive, not merely firm.' },
  { id: 'v-ubiquitous', deck: 'vocab', term: 'Ubiquitous', short: 'adjective', definition: 'Found everywhere at the same time.', example: 'Ubiquitous payment terminals in every shop.', trap: 'It means everywhere, not merely common.' },
  { id: 'v-umbrage', deck: 'vocab', term: 'Umbrage', short: 'noun', definition: 'Offence taken at a perceived slight.', example: 'He took umbrage at the missing invitation.', trap: 'It is almost always used as "take umbrage".' },
  { id: 'v-unequivocal', deck: 'vocab', term: 'Unequivocal', short: 'adjective', definition: 'Leaving no doubt at all, with nothing open to interpretation.', example: 'An unequivocal no from the regulator.', trap: 'It is the opposite of equivocal, which is deliberately unclear.' },
  { id: 'v-untenable', deck: 'vocab', term: 'Untenable', short: 'adjective', definition: 'Impossible to defend or maintain.', example: 'An untenable position once the numbers were published.', trap: 'It means indefensible, not merely unpopular.' },
  { id: 'v-upbraid', deck: 'vocab', term: 'Upbraid', short: 'verb', definition: 'To scold someone firmly for a fault they have committed.', example: 'She upbraided the team for missing the checks.', trap: 'Similar to reprimand, stronger than admonish.' },
  { id: 'v-urbane', deck: 'vocab', term: 'Urbane', short: 'adjective', definition: 'Smoothly polite and socially confident.', example: 'An urbane host who put strangers at ease.', trap: 'Urbane is suave; urban means of the city.' },
  { id: 'v-vacillate', deck: 'vocab', term: 'Vacillate', short: 'verb', definition: 'To keep changing your mind between options.', example: 'The board vacillated for three meetings.', trap: 'It is indecision, not deliberate delay.' },
  { id: 'v-venerate', deck: 'vocab', term: 'Venerate', short: 'verb', definition: 'To regard with deep respect, close to reverence.', example: 'A venerated founder whose rules still stand.', trap: 'It is stronger than admire, close to reverence.' },
  { id: 'v-veracity', deck: 'vocab', term: 'Veracity', short: 'noun', definition: 'Truthfulness, or accuracy of a statement.', example: 'Nobody doubted the veracity of the log files.', trap: 'Veracity is truth; voracity is huge appetite.' },
  { id: 'v-verbose', deck: 'vocab', term: 'Verbose', short: 'adjective', definition: 'Using far more words than needed.', example: 'A verbose memo that buried the decision.', trap: 'Verbose is wordy; pithy is its opposite.' },
  { id: 'v-vilify', deck: 'vocab', term: 'Vilify', short: 'verb', definition: 'To speak about someone in an abusive way that damages them.', example: 'The press vilified the engineer before the facts emerged.', trap: 'Stronger than criticise; it attacks the person.' },
  { id: 'v-vindicate', deck: 'vocab', term: 'Vindicate', short: 'verb', definition: 'To clear of blame, or to prove that something was right.', example: 'The results vindicated the unpopular decision.', trap: 'Vindicate proves right; vindictive means seeking revenge.' },
  { id: 'v-virulent', deck: 'vocab', term: 'Virulent', short: 'adjective', definition: 'Extremely severe or harmful, whether a disease or hostility.', example: 'Virulent criticism from former supporters.', trap: 'It works for both illness and feeling.' },
  { id: 'v-voracious', deck: 'vocab', term: 'Voracious', short: 'adjective', definition: 'Wanting great quantities, of food or of anything else.', example: 'A voracious reader of annual reports.', trap: 'Voracious is hungry; veracious is truthful.' },
  { id: 'v-zealot', deck: 'vocab', term: 'Zealot', short: 'noun', definition: 'Someone whose commitment to a cause is extreme and uncompromising.', example: 'A zealot for process who blocked every exception.', trap: 'Zeal is positive energy; a zealot has taken it too far.' },

  // ---------- Frameworks ----------
  { id: 'force-entrants', deck: 'frameworks', term: 'Threat of new entrants', definition: 'How easily outsiders can enter and erode profit, set by barriers such as capital, scale, regulation, distribution and brand.', example: 'Aircraft manufacturing has huge capital and certification barriers, so six makers hold the regional-jet market.', trap: 'Listing barriers without asking which one actually stops the likely entrant.' },
  { id: 'force-buyers', deck: 'frameworks', term: 'Buyer power', definition: 'How much customers can push price and terms down, strongest when buyers are concentrated, buy in bulk, or face low switching costs.', example: 'Three lessors buying 20 planes at once extracted $6.8M a plane where small buyers paid $8.4M.', trap: 'Blaming rivalry for a margin squeeze that is really concentrated buyer leverage.' },
  { id: 'force-suppliers', deck: 'frameworks', term: 'Supplier power', definition: 'How much suppliers can raise prices or dictate terms, strongest when inputs are critical, differentiated, or single-sourced.', example: 'A sole certified fuel supplier can hold price flat even while shipping lower-grade ore.', trap: 'Checking only price; power also shows up as degrading input quality at the same price.' },
  { id: 'force-substitutes', deck: 'frameworks', term: 'Threat of substitutes', definition: 'Products from outside the industry that meet the same need differently, capping the price the industry can charge.', example: 'Fast charging substitutes for battery swapping even though no rival sells a swap.', trap: 'Scanning only direct competitors while a different model takes the customer.' },
  { id: 'force-rivalry', deck: 'frameworks', term: 'Competitive rivalry', definition: 'How hard existing players fight, worst with many balanced rivals, slow growth, high fixed costs and no differentiation.', example: 'Six similar streaming platforms bidding up content costs is rivalry doing the damage.', trap: 'Calling every margin problem rivalry when the mechanism might be buyers, suppliers, or substitutes.' },
  { id: 'four-cs-fw', deck: 'frameworks', term: '4Cs', definition: 'Customer, company, competition, collaborators: a scan of who buys, what you bring, who else sells, and who helps you reach them.', example: 'A fleet buyer, a premium scooter brand, a cut-price rival, and a leasing partner is a 4Cs read on a fleet entry.', trap: 'Announcing the framework by name instead of letting the four lenses find the facts that matter.' },
  { id: 'dmu', deck: 'frameworks', term: 'Decision-making unit', short: 'DMU', definition: 'The set of roles behind a purchase: who uses, who chooses, who influences, and who pays, which can be four different people.', example: 'In a toy store the child is the user while the parent is the customer who pays.', trap: 'Selling to the user while the buyer with the budget applies different criteria.' },
  { id: 'pestel', deck: 'frameworks', term: 'PESTEL', definition: 'Political, economic, social, technological, environmental and legal forces: a scan of the macro environment around a decision.', example: 'A fintech entry checks lending licences (legal), digitisation (technological), and expat credit habits (social).', trap: 'Producing six boxes of trends with no link to the decision at hand.' },
  { id: 'ansoff', deck: 'frameworks', term: 'Ansoff matrix', definition: 'Growth mapped by new versus existing on two axes: same products in same markets, new markets, new products, or diversification.', example: 'Selling fleet scooters to delivery platforms is existing product, new customer segment.', trap: 'Calling every plan diversification; risk rises sharply only when both axes are new.' },
  { id: 'three-horizons', deck: 'frameworks', term: 'Three horizons', definition: 'Managing today’s business, tomorrow’s scaling bets, and longer-term options as three separate portfolios with different metrics.', example: 'Defend the core route business, scale the booking app, and pilot autonomous vehicles as horizons one to three.', trap: 'Judging a horizon-two bet by the margin standards of the mature core.' },
  { id: 'tco', deck: 'frameworks', term: 'Total cost of ownership', short: 'TCO', definition: 'The full cost of owning something: purchase price plus energy, service, downtime, training and disposal over its life.', example: 'An EV scooter at $65,000 can beat a cheaper petrol one once 30,000 km a year of fuel and service counts.', trap: 'Comparing sticker prices when the buyer lives with operating cost every day.' },
  { id: 'perpetuity', deck: 'frameworks', term: 'Growing perpetuity', definition: 'The value of a cash flow that grows forever at a steady rate: next year’s flow divided by the discount rate minus the growth rate.', example: '$150 million growing at 15% with a 20% hurdle is worth 15 ÷ 0.05 = $3 billion.', trap: 'Using it when growth is close to or above the discount rate, which inflates the result absurdly.' },
  { id: 'dd-pillars', deck: 'frameworks', term: 'Due-diligence pillars', definition: 'The lenses a commercial diligence runs: strategic fit, operational capability, financial viability, and risks or integration gaps.', example: 'Checking city overlap, fill rates, warehouse break-even, and lease renewals before buying a fulfilment network.', trap: 'Ending at “the numbers work” without naming the conditions that would kill the deal.' },
  { id: 'impact-feasibility', deck: 'frameworks', term: 'Impact-feasibility matrix', definition: 'A two-by-two that sorts initiatives by what they are worth against how doable they are, so quick wins come before moonshots.', example: 'Auto-approving low-value refunds is high impact and high feasibility; automating warranty claims is high impact but needs agents longer.', trap: 'Ranking on impact alone and starting with the hardest item on the list.' },
  { id: 'right-to-win-fw', deck: 'frameworks', term: 'Right to win', definition: 'The reason this company, not just any entrant, should succeed: assets such as data, distribution, brand or cost that transfer to the new market.', example: 'A checkout lender wins because the platform already owns the transaction flow and customer history.', trap: 'Pointing at an attractive market when none of the client’s assets give it an edge there.' },
  { id: 'value-pricing', deck: 'frameworks', term: 'Value-based pricing', definition: 'Setting price from what the product is worth to the customer, which also tells you the most you could ever charge.', example: 'A tool saving $16,500 of labour a month has a value ceiling near that, even if launched at $4,500.', trap: 'Charging the full value created; competitors and missing proof pull the real price far below the ceiling.' },
  { id: 'cost-plus-fw', deck: 'frameworks', term: 'Cost-plus pricing', definition: 'Variable and fixed cost plus a target margin sets the floor below which selling loses money, useful as a bound, not a strategy.', example: '$1,600 of variable cost at a 60% margin sets a $4,000 floor.', trap: 'Applying the margin to cost instead of price: cost ÷ (1 − margin), not cost × (1 + margin).' },
  { id: 'expected-value-fw', deck: 'frameworks', term: 'Expected value', definition: 'Each outcome weighted by its probability and summed, the standard way to value a case with uncertain finishes.', example: 'Five possible season finishes, weighted 30/30/25/10/5%, turn into one expected prize-money uplift.', trap: 'Planning for the single most likely outcome and ignoring the tail contributions.' },
  { id: 'scenario-fw', deck: 'frameworks', term: 'Scenario analysis', definition: 'Two or three coherent futures built on the few uncertainties that matter, each with its own decision implication.', example: 'A base case without the subsidy and a verified-incentive case with it, plus a threshold for switching.', trap: 'Averaging the scenarios into one number, which erases the decision the analysis exists to inform.' },
  { id: 'sensitivity-fw', deck: 'frameworks', term: 'Sensitivity analysis', definition: 'Flexing one input at a time to find which assumption moves the answer most, so diligence focuses there.', example: 'A 200-point rise in defaults wipes out two-thirds of a thin lending margin, making defaults the number to underwrite.', trap: 'Treating every input as equally uncertain instead of finding the one that can kill the case.' },
  { id: 'bottom-up-fw', deck: 'frameworks', term: 'Bottom-up estimate', definition: 'Building a size from unit economics: customers times purchases times price, where a top-down share filter misses the mechanics.', example: 'A golf store sized as 80,000 buyers × $100 × 2 purchases, not a share of “the UK golf market”.', trap: 'Applying a percentage to a total you cannot verify, which hides every assumption that matters.' },
  { id: 'benchmarking-fw', deck: 'frameworks', term: 'Benchmarking', definition: 'Comparing a metric against peers or best practice to separate “our problem” from “industry problem”, one like-for-like number at a time.', example: '18 trades a customer versus competitors’ 27 shows a frequency gap, while $22 versus $23 per trade shows pricing is fine.', trap: 'Benchmarking the outcome (revenue) instead of the drivers (trades, penetration) that explain it.' },
  { id: 'profit-tree-fw', deck: 'frameworks', term: 'Profit tree', definition: 'Profit decomposed into revenue and cost, then into price, volume, mix, and unit and fixed costs, so the moving branch is found first.', example: 'Revenue = customers × frequency × basket separates a customer decline from a frequency decline.', trap: 'Cutting costs or raising price before locating which branch actually deteriorated.' },
  { id: 'driver-tree-fw', deck: 'frameworks', term: 'Driver tree', definition: 'A target metric split into the operational drivers that produce it, each level independently measurable.', example: 'ARPU = trades × revenue per trade plus penetration × revenue per product customer.', trap: 'Decomposing into categories you cannot measure or influence, which makes the tree decorative.' },
  { id: 'case-arc-fw', deck: 'frameworks', term: 'Clarify, structure, analyse, conclude', definition: 'The case arc: pin the objective and scope first, build a clean structure, work the numbers aloud, and close top-down.', example: 'Asking how a two-sided platform earns on each side before proposing any lever.', trap: 'Skipping clarification because the brief sounds familiar; a misread scope invalidates everything after it.' },
  { id: 'ai-interview-fw', deck: 'frameworks', term: 'AI-assisted casing', definition: 'Using a model to widen options and pull benchmarks while you keep the structure, verify the numbers, and make the call.', example: 'Draft your own tree first, then ask the model which branch is missing or what would make the conclusion wrong.', trap: 'Reading an unranked, fluent list back as your recommendation; you are scored on the call, not the list.' },

  // ---------- Strategy concepts ----------
  { id: 'two-sided-st', deck: 'strategy', term: 'Two-sided platform', definition: 'A business serving two groups who need each other, where pricing or growth on one side changes the other side’s willingness to stay.', example: 'Raising partner fees on a services platform pushes partners and customers to deal directly, shrinking the network.', trap: 'Pricing one side without asking what it does to the other side.' },
  { id: 'disintermediation-st', deck: 'strategy', term: 'Disintermediation', definition: 'When the parties a platform connects cut out the middle and deal directly, removing the platform’s reason to exist.', example: 'A delivery rider and restaurant exchanging numbers and settling off-app.', trap: 'Treating the fee as pure upside; too high a take rate is what triggers bypass.' },
  { id: 'winners-curse-st', deck: 'strategy', term: 'Winner’s curse', definition: 'In auctions the winner tends to be the bidder who most overestimated the prize, so winning can mean overpaying.', example: 'Bidding above $166.3 million of expected uplift for a star player guarantees a value-destroying win.', trap: 'Raising the bid because rival interest feels like validation of the asset.' },
  { id: 'commoditisation-st', deck: 'strategy', term: 'Commoditisation', definition: 'When differentiation erodes until offers are interchangeable and price becomes the only dimension of competition.', example: 'Identical fuel or bandwidth where buyers switch for a dollar.', trap: 'Investing in brand for a product whose buyers have stopped valuing the difference.' },
  { id: 'cost-leadership-st', deck: 'strategy', term: 'Cost leadership', definition: 'Winning by being the cheapest to serve at acceptable quality, funded by scale, process design, or simpler offerings.', example: 'A standardised single-fleet airline holding inventory cost far below a mixed-fleet rival.', trap: 'Cutting visible quality the customer actually pays for and calling it efficiency.' },
  { id: 'differentiation-st', deck: 'strategy', term: 'Differentiation', definition: 'Earning a premium or loyalty by being meaningfully different on an attribute buyers will pay for.', example: 'In-house original content that exists on no rival platform.', trap: 'Differentiating on something the customer notices but would never pay extra to get.' },
  { id: 'pricing-power-st', deck: 'strategy', term: 'Pricing power', definition: 'The ability to raise price without losing volume, created by differentiation, switching costs, or scarce alternatives.', example: 'A supplier that is the sole certified source can hold price flat even as input quality slips.', trap: 'Testing pricing power by raising prices blind; it is an outcome of structure, not a wish.' },
  { id: 'land-expand-st', deck: 'strategy', term: 'Land and expand', definition: 'Winning a small foothold inside an account or segment, then growing usage and products once inside.', example: 'Starting BNPL users at $150 limits and stepping them up as they repay on time.', trap: 'Discounting hard to land without a plan for how the account expands.' },
  { id: 'freemium-st', deck: 'strategy', term: 'Freemium', definition: 'A free tier that builds reach and a paying tier that monetises a minority, where free users are also the conversion pool.', example: '30 million ad-supported viewers are the reservoir from which 1.5 million premium upgrades can come.', trap: 'Giving away the part people would have paid for, leaving the paid tier without a draw.' },
  { id: 'earnout-st', deck: 'strategy', term: 'Earnout', definition: 'Part of an acquisition price paid only when agreed milestones are met after the deal, shifting performance risk back to the seller.', example: '$1.2 billion upfront, the rest only when fill rate and break-even targets are hit.', trap: 'Tying the earnout to metrics the seller cannot influence after handover.' },
  { id: 'sale-leaseback-st', deck: 'strategy', term: 'Sale-leaseback', definition: 'Selling an asset and renting it back: frees capital and keeps operations running, at the cost of a permanent lease obligation.', example: 'Selling key warehouses to secure occupancy while releasing cash for the turnaround.', trap: 'Reading it as free money; the lease cost returns every year and rent can be repriced.' },
  { id: 'fill-rate-st', deck: 'strategy', term: 'Fill rate', definition: 'The share of demand fulfilled correctly from stock; low fill means stockouts, lost orders and weaker loyalty.', example: 'A warehouse at 82% fill against a 90% benchmark turns away nearly a fifth of orders.', trap: 'Averaging it across all SKUs while the high-velocity items keep stocking out.' },
  { id: 'moat-st', deck: 'strategy', term: 'Economic moat', definition: 'A structural advantage rivals cannot copy cheaply: scale, switching costs, network effects, brand or a cost position.', example: 'Certification plus vertical integration keeps a sole supplier unchallengeable for years.', trap: 'Calling a good product a moat; a moat is what survives a competitor copying the product.' },
  { id: 'min-efficient-scale-st', deck: 'strategy', term: 'Minimum efficient scale', definition: 'The volume a player must reach before unit costs stop being punitive; below it, growth is expensive and profit is hard.', example: 'Jet production at 100 units already spreads fixed cost, so dropping the 60-unit lessor segment breaks the economics.', trap: 'Chasing volume that costs more to make than it earns, just to reach a nominal scale.' },
  { id: 'lock-in-st', deck: 'strategy', term: 'Lock-in', definition: 'A structure where leaving costs the customer enough that they stay, built from data, integrations, contracts or learned habits.', example: 'An AI assistant embedded across laptops and phones deepens lock-in each device cycle.', trap: 'Building lock-in through friction that annoys customers into leaving anyway.' },
  { id: 'flywheel-st', deck: 'strategy', term: 'Flywheel effect', definition: 'A self-reinforcing loop where each output feeds the next input, so advantage compounds rather than resetting each period.', example: 'Fleet scooters doing 3-4 times the mileage generate battery data that improves the product that wins more fleet orders.', trap: 'Drawing a circular diagram of unconnected activities; a flywheel must physically feed itself.' },
  { id: 'asset-light-st', deck: 'strategy', term: 'Asset-light model', definition: 'Owning the customer and orchestration while partners carry the heavy assets, which scales fast but cedes control.', example: 'A delivery platform outsourcing 100% of last-mile vehicles to hyperlocal aggregators.', trap: 'Praising the low capital while ignoring the SLA control you just handed away.' },
  { id: 'skimming-penetration-st', deck: 'strategy', term: 'Skimming vs penetration pricing', definition: 'Skim high into eager early buyers, or price low to flood the market; the choice trades margin now for share later or vice versa.', example: 'Launching at $4,500 against a $4,500 competitor, not at the $16,500 value ceiling.', trap: 'Pricing for a strategy you did not choose, such as premium price on a penetration plan.' },
  { id: 'razor-blades-st', deck: 'strategy', term: 'Razor-and-blades model', definition: 'Sell the platform cheap and earn on the consumables or services that only fit it.', example: 'Thin hardware margin on a fleet scooter recovered through service visits and battery swaps.', trap: 'Counting only the hardware margin while forgetting the annuity the model is built on.' },
  { id: 'loss-leader-st', deck: 'strategy', term: 'Loss leader', definition: 'A product sold below cost to pull in customers who buy profitably alongside it.', example: 'A free consulting diagnostic that opens the door to a paid engagement.', trap: 'A loss leader only works if the companion economics are real and measured.' },
  { id: 'winner-takes-most-st', deck: 'strategy', term: 'Winner-takes-most market', definition: 'Where share concentrates because network effects, scale or data advantages reward the leader disproportionately.', example: 'In a market where 80% is held by four majors, a fifth player must find a niche or the economics never normalise.', trap: 'Assuming a modest share is stable in a market structure that keeps tipping.' },
  { id: 'cross-side-st', deck: 'strategy', term: 'Cross-side network effects', definition: 'Growth on one side of a platform raising value for the other side, unlike same-side effects which often reduce it.', example: 'More merchants make a payments platform more useful to shoppers, and more shoppers pull in merchants.', trap: 'Claiming network effects where more users on the same side only compete with each other.' },
  { id: 'path-dependence-st', deck: 'strategy', term: 'Path dependence', definition: 'When earlier choices lock in later options, so a technically worse standard can persist because switching is costly.', example: 'A firm that built on one cloud cannot easily move its AI stack to another.', trap: 'Comparing future options on merit while forgetting the cost of leaving the current path.' },
  { id: 'channel-conflict-st', deck: 'strategy', term: 'Channel conflict', definition: 'When a new route to market competes with the channel that already sells for you, inviting retaliation or boycott.', example: 'Selling fleet scooters direct while dealers still carry the retail line, or pricing direct below what partners can charge.', trap: 'Launching the new channel without deciding who owns the shared customer.' },
  { id: 'recurring-revenue-st', deck: 'strategy', term: 'Recurring revenue', definition: 'Income that repeats without a fresh sale, subscriptions, service contracts or usage annuities, valued higher than one-off sales.', example: 'A leasing model converts one thin scooter sale into years of service and battery income.', trap: 'Booking the full contract value in year one instead of spreading it over the term.' },
  { id: 'structural-cost-st', deck: 'strategy', term: 'Structural cost advantage', definition: 'A cost edge that comes from the business model rather than effort, so rivals cannot copy it by working harder.', example: 'A single standardised fleet holding far fewer spare parts than a rival flying five aircraft types.', trap: 'Mistaking a procurement discount for a structural edge anyone could negotiate.' },
  { id: 'second-mover-st', deck: 'strategy', term: 'Second-mover advantage', definition: 'The follower’s gain: learning from the pioneer’s mistakes, adopting proven demand, and skipping the education cost.', example: 'Letting a rival prove fleet demand, then entering with a leasing model that fixes their uptime complaints.', trap: 'Assuming early always wins; often the pioneer’s mistakes are the follower’s free lessons.' },
]
